window.SITE_TOWNS = [{"id":"deva","name":"Deva","category":{"ro":"Municipiu","en":"Municipality"},"area":"Culoarul Mureșului","coords":[45.8781,22.9144],"hasReviews":false,"relatedAreas":["Deva"],"images":["images/deva-cetate.jpg"],"photoCredit":{"author":"Bogdan.onis","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Cetatea_Deva.jpg"},"ro":{"tagline":"Reședința județului Hunedoara, dominată de Cetatea Deva, pe un deal vulcanic în mijlocul orașului.","description":["Deva este centrul administrativ al județului, așezat pe Mureș. Simbolul orașului este Cetatea Deva, ruine medievale aflate pe un deal vulcanic chiar în centrul orașului, accesibile pe jos sau cu minibuzul electric (telecabina este oprită din noiembrie 2025).","În centrul istoric se află Magna Curia (Palatul Bethlen, 1621), care găzduiește azi Muzeul Civilizației Dacice și Romane. Deva e cunoscută și ca centru național al gimnasticii românești."],"facts":[{"label":"Populație","value":"53.113 locuitori (recensământ 2021)"},{"label":"Reper","value":"Cetatea Deva (acces pe jos sau cu minibuzul electric)"},{"label":"Muzeu","value":"Magna Curia — Muzeul Civilizației Dacice și Romane"}]},"en":{"tagline":"The seat of Hunedoara county, overlooked by Deva Citadel on a volcanic hill right in the city centre.","description":["Deva is the county's administrative centre, on the Mureș river. The city's landmark is Deva Citadel, medieval ruins on a volcanic hill in the middle of town, reachable on foot or by electric minibus (the cable car has been out of service since November 2025).","The old centre holds Magna Curia (Bethlen Castle, 1621), now home to the Museum of Dacian and Roman Civilisation. Deva is also known as a national centre for Romanian gymnastics."],"facts":[{"label":"Population","value":"53,113 (2021 census)"},{"label":"Landmark","value":"Deva Citadel (on foot or by electric minibus)"},{"label":"Museum","value":"Magna Curia — Museum of Dacian and Roman Civilisation"}]}},{"id":"hunedoara","name":"Hunedoara","category":{"ro":"Municipiu","en":"Municipality"},"area":"Culoarul Mureșului","coords":[45.7697,22.9203],"hasReviews":false,"relatedAreas":["Hunedoara"],"relatedIds":["cheile-cernei","traseu-hunedoara-lacul-cincis-cheile-cernei","traseu-hunedoara-varful-rusca","lacul-cincis"],"images":["images/hunedoara-corvin-castle.jpg"],"photoCredit":{"author":"Andrei Stroe","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Corvin_castle.jpg"},"ro":{"tagline":"Orașul Castelului Corvinilor, unul dintre cele mai mari castele medievale din Europa.","description":["Hunedoara a fost multă vreme un important centru siderurgic, dar rămâne cunoscută în primul rând pentru Castelul Corvinilor (Castelul Huniazilor), ridicat în secolul al XV-lea de Iancu de Hunedoara — unul dintre cele mai mari castele gotico-renascentiste din Europa și unul dintre cele „7 minuni ale României”.","Castelul, cu Sala Cavalerilor, Sala Dietei și turnurile sale, se vizitează pe tot parcursul anului și este iluminat seara."],"facts":[{"label":"Populație","value":"50.457 locuitori (recensământ 2021)"},{"label":"Reper","value":"Castelul Corvinilor (secolul XV)"}]},"en":{"tagline":"Home to Corvin Castle, one of Europe's largest medieval castles.","description":["Hunedoara was long an important steel-industry centre, but is best known for Corvin Castle (Hunyadi Castle), built in the 15th century by John Hunyadi — one of the largest Gothic-Renaissance castles in Europe and one of the \"7 Wonders of Romania\".","The castle, with its Knights' Hall, Diet Hall and towers, can be visited year-round and is lit up in the evening."],"facts":[{"label":"Population","value":"50,457 (2021 census)"},{"label":"Landmark","value":"Corvin Castle (15th century)"}]}},{"id":"simeria","name":"Simeria","category":{"ro":"Oraș","en":"Town"},"area":"Culoarul Mureșului","coords":[45.8514,23.0139],"hasReviews":false,"relatedAreas":["Simeria"],"images":["images/simeria-panorama.jpg"],"photoCredit":{"author":"Razvanus","license":"domeniu public","source":"https://commons.wikimedia.org/wiki/File:Gara_din_Simeria.JPG"},"ro":{"tagline":"Oraș născut din prima cale ferată a Transilvaniei, cu cel mai vechi și mai mare parc dendrologic din România.","description":["Simeria a apărut ca o colonie a constructorilor de cale ferată în 1866–1867 și a crescut odată cu linia Arad–Alba Iulia — prima cale ferată din Transilvania, deschisă în 1868 — devenind un nod feroviar important, cu ramificația spre Valea Jiului inaugurată în 1870. S-a desprins administrativ de comuna Biscaria în 1891 și a primit statut de oraș în 1952.","Pe teritoriul orașului se află Arboretumul Simeria (Parcul Dendrologic Simeria), fostul parc al conacului familiei Gyulay, documentat din 1763 și transformat în 1949 în parc dendrologic — azi una dintre cele mai valoroase colecții de arbori și arbuști din România."],"facts":[{"label":"Populație","value":"11.268 locuitori (recensământ 2021)"},{"label":"Statut","value":"oraș (din 1952)"},{"label":"Reper","value":"Arboretumul Simeria — Parcul Dendrologic Simeria"},{"label":"Nod feroviar","value":"pe prima cale ferată din Transilvania (Arad–Alba Iulia, 1868)"}]},"en":{"tagline":"A town born out of Transylvania's first railway, home to Romania's oldest and largest dendrological park.","description":["Simeria began as a railway workers' colony in 1866–1867 and grew alongside the Arad–Alba Iulia line — Transylvania's first railway, opened in 1868 — becoming an important railway junction once the branch line to the Jiu Valley opened in 1870. It split administratively from Biscaria commune in 1891 and gained town status in 1952.","The town also holds the Simeria Arboretum (Simeria Dendrological Park), the former park of the Gyulay family manor, documented since 1763 and turned into a dendrological park in 1949 — today one of Romania's most valuable collections of trees and shrubs."],"facts":[{"label":"Population","value":"11,268 (2021 census)"},{"label":"Status","value":"town (since 1952)"},{"label":"Landmark","value":"Simeria Arboretum — Simeria Dendrological Park"},{"label":"Railway junction","value":"on Transylvania's first railway (Arad–Alba Iulia, 1868)"}]}},{"id":"petrosani","name":"Petroșani","category":{"ro":"Municipiu","en":"Municipality"},"area":"Valea Jiului","coords":[45.4166,23.3733],"hasReviews":false,"relatedAreas":["Petroșani","Parâng","Vâlcan","Uricani","Bănița"],"images":["images/petrosani-panorama.jpg"],"photoCredit":{"author":"Eduard Gergely","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Petrosani_Town.jpg"},"ro":{"tagline":"Orașul universitar al Văii Jiului și poarta spre platoul Parâng.","description":["Petroșani este orașul principal al Văii Jiului, centru al bazinului carbonifer și sediul Universității din Petroșani — continuatoarea Institutului de Mine, care funcționează aici din 1948.","Din oraș pornește telescaunul care urcă spre platoul Parâng, una dintre cele mai apropiate zone de schi și drumeție din județ."],"facts":[{"label":"Populație","value":"31.044 locuitori (recensământ 2021)"},{"label":"Reper","value":"Universitatea din Petroșani (din 1948, fost Institut de Mine)"},{"label":"Poartă spre","value":"Platoul Parâng (telescaun)"}]},"en":{"tagline":"The university town of the Jiu Valley and the gateway to the Parâng plateau.","description":["Petroșani is the main town of the Jiu Valley, the centre of the coal basin and home to the University of Petroșani — successor of the Mining Institute, operating here since 1948.","A chairlift from the town goes up to the Parâng plateau, one of the county's closest ski and hiking areas."],"facts":[{"label":"Population","value":"31,044 (2021 census)"},{"label":"Landmark","value":"University of Petroșani (since 1948, formerly the Mining Institute)"},{"label":"Gateway to","value":"Parâng plateau (chairlift)"}]}},{"id":"petrila","name":"Petrila","category":{"ro":"Oraș","en":"Town"},"area":"Valea Jiului","coords":[45.453,23.416],"hasReviews":false,"relatedAreas":["Petrila","Parâng"],"relatedIds":["cabana-brazihouse-petrila","cabana-taia-parang-sureanu-petrila"],"images":["images/petrila-panorama.jpg"],"photoCredit":{"author":"Loraine","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Petrila_view.jpg"},"ro":{"tagline":"Cel mai vechi oraș minier al Văii Jiului, azi poartă spre Cheile Jiețului și fosta mină devenită muzeu.","description":["Petrila este atestată documentar din 1499 și s-a dezvoltat de la 1840 ca centru minier, în jurul minelor Lonea și Petrila. Mina, închisă în 2015, a fost clasată monument istoric și transformată treptat în „Planeta Petrila” — un muzeu în aer liber cu tururi ghidate și festivalul Opera Nights.","Pe teritoriul orașului se află și rezervațiile naturale Cheile Jiețului (10 ha) și Cheile Taia (2 ha), punct de plecare spre platoul Parâng, precum și Conacul Rădăcinilor, un complex hotelier și de agrement deschis în 2023 în Cheile Jietului."],"facts":[{"label":"Populație","value":"19.600 locuitori (recensământ 2021)"},{"label":"Atestare documentară","value":"1499"},{"label":"Reper","value":"Mina Petrila / Planeta Petrila (monument istoric)"}]},"en":{"tagline":"The oldest mining town of the Jiu Valley, now a gateway to the Jieț Gorge and its former mine turned museum.","description":["Petrila is first documented in 1499 and grew from the 1840s as a mining centre, around the Lonea and Petrila mines. The mine, closed in 2015, was listed as a historic monument and gradually turned into \"Planet Petrila\" — an open-air museum with guided tours and the Opera Nights festival.","The town's territory also holds the Jieț Gorge (10 ha) and the Taia Gorge (2 ha) nature reserves, a starting point for the Parâng plateau, as well as Conacul Rădăcinilor, a hotel and leisure complex opened in 2023 in the Jieț gorge."],"facts":[{"label":"Population","value":"19,600 (2021 census)"},{"label":"First documented","value":"1499"},{"label":"Landmark","value":"Petrila Mine / Planet Petrila (historic monument)"}]}},{"id":"vulcan","name":"Vulcan","category":{"ro":"Municipiu","en":"Municipality"},"area":"Valea Jiului","coords":[45.3833,23.2667],"hasReviews":false,"relatedAreas":["Vulcan","Vâlcan"],"images":["images/vulcan-panorama.jpg"],"photoCredit":{"author":"Bogdan Muraru","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Prim%C4%83ria_Vulcan.jpg"},"ro":{"tagline":"A doua localitate ca mărime din Valea Jiului, poartă spre Pasul Vulcan și Peștera Dracului.","description":["Vulcan apare menționat încă din Harta Iosefină (1769–1773) și este, din 2003, municipiu — a doua localitate ca mărime din Valea Jiului, după Petroșani. Orașul s-a dezvoltat tot în jurul mineritului cărbunelui, iar astăzi e cunoscut mai ales pentru Peștera Dracului, cu propria cascadă, aflată pe unul dintre cele cinci trasee tematice amenajate în zonă în 2022.","De la Vulcan pornește drumul spre Pasul Vulcan (1.621 m), care leagă Valea Jiului de nordul Olteniei, traversat istoric de Mihai Viteazul în 1600 și loc de luptă în Primul Război Mondial."],"facts":[{"label":"Populație","value":"19.772 locuitori (recensământ 2021)"},{"label":"Statut","value":"municipiu (din 2003)"},{"label":"Reper","value":"Peștera Dracului; Pasul Vulcan (1.621 m)"}]},"en":{"tagline":"The second-largest town in the Jiu Valley, gateway to Vulcan Pass and the Devil's Cave.","description":["Vulcan is mentioned as far back as the Josephine Land Survey (1769–1773) and has been a municipality since 2003 — the second-largest town in the Jiu Valley after Petroșani. Like its neighbours, it grew around coal mining, and today it's best known for the Devil's Cave (Peștera Dracului), with its own waterfall, found on one of five themed trails built in the area in 2022.","From Vulcan, the road climbs to Vulcan Pass (1,621 m), which links the Jiu Valley to northern Oltenia — historically crossed by Prince Michael the Brave in 1600, and the site of fighting during World War I."],"facts":[{"label":"Population","value":"19,772 (2021 census)"},{"label":"Status","value":"municipality (since 2003)"},{"label":"Landmark","value":"Devil's Cave; Vulcan Pass (1,621 m)"}]}},{"id":"lupeni","name":"Lupeni","category":{"ro":"Municipiu","en":"Municipality"},"area":"Valea Jiului","coords":[45.3603,23.2383],"hasReviews":false,"relatedAreas":["Lupeni","Vâlcan"],"relatedIds":["complexul-montana-lupeni"],"images":["images/lupeni-panorama.jpg"],"photoCredit":{"author":"Mitasim","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Panoram%C4%83_a_municipiului_Lupeni,_Hunedoara.jpg"},"ro":{"tagline":"Oraș din vestul Văii Jiului, poartă spre stațiunea Straja și scenă a marilor greve miniere.","description":["Lupeni este atestat documentar din 1770, a primit rangul de oraș în 1960 și e municipiu din 2003 — al treilea ca mărime din Valea Jiului, la circa 18 km de Petroșani. S-a dezvoltat ca centru minier și a rămas legat de istoria mișcării muncitorești din zonă, fiind scena Grevei de la Lupeni din 1929 și a Grevei minerilor din Valea Jiului din 1977.","De la Lupeni pornește drumul spre stațiunea de schi Straja, aflată la aproximativ 8 km, situată pe versanții Munților Vâlcan."],"facts":[{"label":"Populație","value":"18.699 locuitori (recensământ 2021)"},{"label":"Atestare documentară","value":"1770"},{"label":"Statut","value":"municipiu (din 2003, oraș din 1960)"},{"label":"Poartă spre","value":"Stațiunea Straja (cca. 8 km)"}]},"en":{"tagline":"A town in the west of the Jiu Valley, gateway to the Straja resort and the stage of major miners' strikes.","description":["Lupeni is first documented in 1770, was granted town status in 1960 and has been a municipality since 2003 — the third-largest town in the Jiu Valley, about 18 km from Petroșani. It grew as a coal-mining centre and remains tied to the region's labour history, having been the site of the 1929 Lupeni strike and the 1977 Jiu Valley miners' strike.","The road from Lupeni leads to the Straja ski resort, about 8 km away, on the slopes of the Vâlcan Mountains."],"facts":[{"label":"Population","value":"18,699 (2021 census)"},{"label":"First documented","value":"1770"},{"label":"Status","value":"municipality (since 2003, town since 1960)"},{"label":"Gateway to","value":"Straja resort (approx. 8 km)"}]}},{"id":"aninoasa","name":"Aninoasa","category":{"ro":"Oraș","en":"Town"},"area":"Valea Jiului","coords":[45.4111,23.3139],"hasReviews":false,"relatedAreas":["Aninoasa"],"images":["images/aninoasa-exploatarea-miniera.jpg"],"photoCredit":{"author":"autor necunoscut (Muzeul Național de Istorie a României)","license":"domeniu public","source":"https://commons.wikimedia.org/wiki/File:Exploatarea_miniera_Aninoasa.JPG"},"ro":{"tagline":"Cel mai mic oraș al județului, crescut în jurul minei de cărbune, între Petroșani și Vulcan.","description":["Aninoasa este un oraș din Valea Jiului, format din localitatea Aninoasa și satul Iscroni, întins de-a lungul pârâului Aninoasa, aproape de confluența Jiului de Vest cu Jiul de Est, la circa 7 km de Petroșani și 5 km de Vulcan. Numele vine de la anin (arin).","Localitatea s-a dezvoltat odată cu mineritul: exploatarea cărbunelui a început în anii 1880, când a fost construită și prima colonie muncitorească. Aninoasa a fost declarată oraș în 1989, când avea peste 6.000 de locuitori, iar mina a fost închisă definitiv în primăvara lui 2006, după un declin prelungit.","Din Vulcan, pe Valea Ungurului, coboară până în Aninoasa Traseul Ruinelor, o potecă tematică de circa 12 km, iar orașul se află și pe circuitul de drumeție Petroșani – Dealul Babii – Bănița."],"facts":[{"label":"Populație","value":"3.369 locuitori (recensământ 2021)"},{"label":"Oraș din","value":"1989"},{"label":"Mina Aninoasa","value":"exploatare începută în anii 1880, închisă în 2006"},{"label":"Localități componente","value":"Aninoasa, Iscroni"}]},"en":{"tagline":"The county's smallest town, grown around its coal mine, between Petroșani and Vulcan.","description":["Aninoasa is a Jiu Valley town made up of Aninoasa itself and the village of Iscroni, stretched along the Aninoasa stream near the confluence of the Western and Eastern Jiu rivers, about 7 km from Petroșani and 5 km from Vulcan. Its name comes from anin, the Romanian word for alder.","The town grew with mining: coal extraction began in the 1880s, when its first workers' colony was also built. Aninoasa was declared a town in 1989, when it had over 6,000 inhabitants, and the mine closed for good in spring 2006, after a long decline.","Traseul Ruinelor, a themed trail of about 12 km, runs from Vulcan down the Valea Ungurului to Aninoasa, and the town also lies on the Petroșani – Dealul Babii – Bănița hiking loop."],"facts":[{"label":"Population","value":"3,369 (2021 census)"},{"label":"Town since","value":"1989"},{"label":"Aninoasa mine","value":"mining began in the 1880s, closed in 2006"},{"label":"Component localities","value":"Aninoasa, Iscroni"}]}},{"id":"orastie","name":"Orăștie","category":{"ro":"Municipiu","en":"Municipality"},"area":"Zona cetăților dacice","coords":[45.85,23.2],"hasReviews":false,"relatedAreas":["Orăștie","Munții Orăștiei","Aurel Vlaicu"],"relatedIds":["traseu-costesti-sarmizegetusa-regia-varful-godeanu","traseu-costesti-cetatea-blidaru-varful-godeanu","traseu-cetatea-fetele-albe","traseu-gradistea-cetatea-piatra-rosie-cioclovina"],"images":["images/orastie-cetate.jpg"],"photoCredit":{"author":"Roamata","license":"domeniu public","source":"https://commons.wikimedia.org/wiki/File:Cetatea_orastie.JPG"},"ro":{"tagline":"Poarta de acces spre Cetățile dacice din Munții Orăștiei, patrimoniu UNESCO.","description":["Orăștie este orașul de la poalele Munților Orăștiei, cel mai apropiat punct de plecare spre cetățile dacice — printre care Sarmizegetusa Regia, capitala regatului lui Decebal — incluse pe lista patrimoniului mondial UNESCO din 1999."],"facts":[{"label":"Populație","value":"16.825 locuitori (recensământ 2021)"},{"label":"Reper","value":"Poartă spre cetățile dacice (UNESCO)"}]},"en":{"tagline":"The gateway to the Dacian Fortresses of the Orăștie Mountains, a UNESCO World Heritage site.","description":["Orăștie sits at the foot of the Orăștie Mountains, the closest starting point for the Dacian fortresses — including Sarmizegetusa Regia, the capital of Decebalus's kingdom — listed as UNESCO World Heritage since 1999."],"facts":[{"label":"Population","value":"16,825 (2021 census)"},{"label":"Landmark","value":"Gateway to the Dacian fortresses (UNESCO)"}]}},{"id":"hateg","name":"Hațeg","category":{"ro":"Oraș","en":"Town"},"area":"Țara Hațegului","coords":[45.6075,22.95],"hasReviews":false,"relatedAreas":["Hațeg","Țara Hațegului","Parcul Național Retezat","Silvașu de Sus, Țara Hațegului"],"relatedIds":["traseu-baru-varful-tulisa","traseu-baru-varful-lola-porumbelu"],"images":["images/hateg-rezervatia-zimbri.jpg"],"photoCredit":{"author":"Radu Niculița","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:14-18-hateg-zimbrii-2.jpg"},"ro":{"tagline":"Poarta spre Parcul Național Retezat și Geoparcul Dinozaurilor din Țara Hațegului.","description":["Hațeg este orașul central al Țării Hațegului, cel mai bun punct de plecare spre Parcul Național Retezat — înființat în 1935, cel mai vechi din România — și spre Geoparcul UNESCO Țara Hațegului, cunoscut pentru fosilele de dinozauri pitici."],"facts":[{"label":"Populație","value":"8.793 locuitori (recensământ 2021)"},{"label":"Reper","value":"Poartă spre Parcul Național Retezat (1935) și Geoparcul Țara Hațegului"}]},"en":{"tagline":"The gateway to Retezat National Park and the Hațeg Country Dinosaurs Geopark.","description":["Hațeg is the central town of Țara Hațegului, the best starting point for Retezat National Park — established in 1935, the oldest in Romania — and for the Hațeg Country UNESCO Global Geopark, known for its dwarf dinosaur fossils."],"facts":[{"label":"Population","value":"8,793 (2021 census)"},{"label":"Landmark","value":"Gateway to Retezat National Park (1935) and the Hațeg Country Geopark"}]}},{"id":"brad","name":"Brad","category":{"ro":"Municipiu","en":"Municipality"},"area":"Munții Metaliferi","coords":[46.1294,22.79],"hasReviews":false,"relatedAreas":["Brad"],"images":["images/brad-skyline.jpg"],"photoCredit":{"author":"Sthadrian","license":"domeniu public","source":"https://commons.wikimedia.org/wiki/File:Brad_Skyline.jpg"},"ro":{"tagline":"Orașul aurului — istoric centru minier, cu propriul muzeu al aurului.","description":["Brad este centrul istoric al mineritului aurifer din Munții Metaliferi. Găzduiește Muzeul Aurului, unul dintre puținele muzee de acest tip din lume, iar în apropiere se află Săcărâmb, localitate cunoscută în mineralogie ca loc de descoperire (1835) a silvanitului, un mineral rar de aur și argint."],"facts":[{"label":"Populație","value":"12.690 locuitori (recensământ 2021)"},{"label":"Reper","value":"Muzeul Aurului"},{"label":"În apropiere","value":"Săcărâmb — localitate-tip pentru mineralul silvanit (1835)"}]},"en":{"tagline":"The city of gold — a historic mining centre, with its own gold museum.","description":["Brad is the historic centre of gold mining in the Metaliferi Mountains. It houses the Gold Museum, one of the few museums of its kind in the world, and nearby lies Săcărâmb, known in mineralogy as the discovery site (1835) of sylvanite, a rare gold-silver mineral."],"facts":[{"label":"Population","value":"12,690 (2021 census)"},{"label":"Landmark","value":"Gold Museum"},{"label":"Nearby","value":"Săcărâmb — type locality of sylvanite (1835)"}]}},{"id":"uricani","name":"Uricani","category":{"ro":"Oraș","en":"Town"},"area":"Valea Jiului","coords":[45.3364,23.1525],"hasReviews":false,"relatedAreas":["Uricani"],"relatedIds":["traseu-campusel-saua-scorota"],"images":["images/uricani-panorama.jpg"],"photoCredit":{"author":"Lejereanu","license":"domeniu public","source":"https://commons.wikimedia.org/wiki/File:3_iulie_07_(4).JPEG"},"ro":{"tagline":"Orașul din capătul vestic al Văii Jiului, întins pe Jiul de Vest la poalele Retezatului și ale Munților Vâlcan.","description":["Uricani este ultimul oraș din Valea Jiului spre vest, așezat pe Jiul de Vest, la 650–750 m altitudine, între Munții Retezat și Munții Vâlcan. Orașul cuprinde localitățile Uricani, Câmpu lui Neag și Valea de Brazi și se întinde mult de-a lungul văii, pe drumul DN66A care vine dinspre Lupeni.","Localitatea a crescut odată cu mineritul: în 1947 s-a deschis prima galerie, în Plaiu Balomir, iar exploatarea huilei a făcut din Uricani un oraș aproape monoindustrial, ridicat la rang de oraș în anii '60. La Câmpu lui Neag, în 1987, o parte din sat a fost demolată pentru o carieră de cărbune; după 1989 exploatarea s-a oprit, iar în locul ei a rămas un lac adânc.","Azi Uricani e una dintre porțile de intrare în Parcul Național Retezat: din Câmpu lui Neag pornesc traseele spre Cheile Buții și Retezatul calcaros, iar drumul transmontan spre Gorj trece pe lângă lacul de acumulare Valea de Pești."],"facts":[{"label":"Populație","value":"6.669 locuitori (recensământ 2021)"},{"label":"Localități componente","value":"Uricani, Câmpu lui Neag, Valea de Brazi"},{"label":"Altitudine","value":"650–750 m, pe Jiul de Vest"},{"label":"Acces","value":"DN66A, prin Lupeni"},{"label":"Reper","value":"poartă spre Parcul Național Retezat (prin Câmpu lui Neag)"}]},"en":{"tagline":"The town at the western end of the Jiu Valley, stretched along the Western Jiu at the foot of the Retezat and Vâlcan mountains.","description":["Uricani is the westernmost town of the Jiu Valley, on the Western Jiu river at 650–750 m, between the Retezat and Vâlcan mountains. The town takes in Uricani, Câmpu lui Neag and Valea de Brazi and stretches a long way along the valley, on the DN66A road coming from Lupeni.","It grew with mining: the first gallery opened in 1947 at Plaiu Balomir, and hard-coal extraction made Uricani an almost single-industry place, given town status in the 1960s. At Câmpu lui Neag, part of the village was demolished in 1987 for an open-pit coal mine; mining stopped after 1989 and a deep lake now fills the pit.","Today Uricani is one of the gateways to Retezat National Park: from Câmpu lui Neag trails lead to the Buta Gorges and the limestone Retezat, and the mountain road to Gorj passes the Valea de Pești reservoir."],"facts":[{"label":"Population","value":"6,669 (2021 census)"},{"label":"Component localities","value":"Uricani, Câmpu lui Neag, Valea de Brazi"},{"label":"Altitude","value":"650–750 m, on the Western Jiu"},{"label":"Access","value":"DN66A, via Lupeni"},{"label":"Landmark","value":"gateway to Retezat National Park (via Câmpu lui Neag)"}]}},{"id":"geoagiu","name":"Geoagiu","category":{"ro":"Oraș","en":"Town"},"area":"Culoarul Mureșului","coords":[45.92,23.2],"hasReviews":false,"relatedAreas":["Geoagiu","Aurel Vlaicu"],"relatedIds":["statiunea-geoagiu-bai","termele-romane-germisara"],"images":["images/geoagiu-rotonda.jpg"],"photoCredit":{"author":"Thaler Tamas","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:AlgyogyFotoThalerTamas.jpg"},"ro":{"tagline":"Orașul de la vărsarea Geoagiului în Mureș, cu stațiunea Geoagiu-Băi și una dintre cele mai vechi biserici din România.","description":["Geoagiu se află la vărsarea râului Geoagiu în Mureș, la poalele de sud-est ale Munților Metaliferi. Pe lângă orașul propriu-zis, cuprinde zece sate, între care stațiunea balneoclimaterică Geoagiu-Băi și satul Aurel Vlaicu, locul natal al pionierului aviației române.","În oraș se află Rotonda — capela romanică din Geoagiu, o biserică de plan circular zidită din cărămidă romană refolosită. Cercetările arheologice din 1993–2004 au găsit în jurul ei peste 200 de morminte, cele mai vechi de la sfârșitul secolului al XI-lea, ceea ce o face, probabil, cea mai veche biserică medievală de pe teritoriul României; azi se vizitează ca muzeu.","Alături stă biserica reformată, gotică (secolele XV–XVI), cu reliefuri romane zidite în pereții exteriori și o orgă din 1870 care funcționează și azi. În Geoagiu-Băi se pot vedea termele romane Germisara, iar la Aurel Vlaicu, casa memorială a inventatorului."],"facts":[{"label":"Populație","value":"5.087 locuitori (recensământ 2021)"},{"label":"Sate","value":"Aurel Vlaicu, Băcâia, Bozeș, Cigmău, Gelmar, Geoagiu-Băi, Homorod, Mermezeu-Văleni, Renghet, Văleni"},{"label":"Reper","value":"Rotonda — capela romanică (probabil sf. sec. XI)"},{"label":"Stațiune","value":"Geoagiu-Băi, ape termale și termele romane Germisara"}]},"en":{"tagline":"The town where the Geoagiu meets the Mureș, with the Geoagiu-Băi spa and one of Romania's oldest churches.","description":["Geoagiu lies where the Geoagiu river flows into the Mureș, at the south-eastern foot of the Metaliferi Mountains. Besides the town itself it takes in ten villages, including the Geoagiu-Băi spa resort and the village of Aurel Vlaicu, birthplace of the Romanian aviation pioneer.","The town has the Rotunda — Geoagiu's Romanesque chapel, a circular church built of reused Roman brick. Excavations in 1993–2004 found more than 200 graves around it, the oldest from the late 11th century, which probably makes it the oldest medieval church on Romanian territory; today it can be visited as a museum.","Next to it is the Gothic Reformed church (15th–16th centuries), with Roman reliefs set into its outer walls and an 1870 organ that still plays. Geoagiu-Băi has the Roman baths of Germisara, and Aurel Vlaicu village the inventor's memorial house."],"facts":[{"label":"Population","value":"5,087 (2021 census)"},{"label":"Villages","value":"Aurel Vlaicu, Băcâia, Bozeș, Cigmău, Gelmar, Geoagiu-Băi, Homorod, Mermezeu-Văleni, Renghet, Văleni"},{"label":"Landmark","value":"The Rotunda — Romanesque chapel (probably late 11th century)"},{"label":"Spa","value":"Geoagiu-Băi, thermal waters and the Roman baths of Germisara"}]}},{"id":"calan","name":"Călan","category":{"ro":"Oraș","en":"Town"},"area":"Valea Streiului","coords":[45.7361,23.0086],"hasReviews":false,"relatedAreas":["Călan"],"relatedIds":["biserica-strei"],"images":["images/calan-biserica-streisangeorgiu.jpg"],"photoCredit":{"author":"Alexandru Baboș (Albabos)","license":"CC BY-SA 3.0 / GFDL","source":"https://commons.wikimedia.org/wiki/File:Streisangeorgiu_HD.SE.jpg"},"ro":{"tagline":"Oraș siderurgic pe valea Streiului, cu băi romane și două dintre cele mai vechi biserici de piatră din Transilvania.","description":["Călan se află pe valea Streiului, între Simeria și Hațeg. Atestat documentar în 1387, a fost în epoca romană Aquae, o așezare cunoscută pentru apele ei calde; băile romane de la Călan au rămas folosite până în vremurile moderne.","Orașul modern s-a născut în jurul uzinei de fier: fundația primului furnal a fost turnată în 1869, producția a început în 1870, iar după al Doilea Război Mondial Călanul a devenit un centru important al siderurgiei românești, cu Combinatul Siderurgic Victoria. Orașul Nou Călan a fost construit din 1959, pe terasa de lângă Streisângeorgiu.","Cele mai valoroase monumente sunt bisericile medievale din satele orașului: Biserica Sf. Gheorghe din Streisângeorgiu, zidită în 1313–1314 după inscripția din altar, cu pictură din 1313–1314, 1409 și 1743 și lespezi romane în ziduri, și biserica din Strei, din jurul anului 1300."],"facts":[{"label":"Populație","value":"10.055 locuitori (recensământ 2021)"},{"label":"Atestare","value":"1387; în epoca romană — Aquae"},{"label":"Industrie","value":"uzina de fier (primul furnal 1869–1870), apoi Combinatul Siderurgic Victoria"},{"label":"Reper","value":"Biserica Sf. Gheorghe din Streisângeorgiu (1313–1314), cod LMI HD-II-m-A-03454"},{"label":"Localități","value":"Călan, Streisângeorgiu și satele Batiz, Călanu Mic, Grid, Nădăștia de Jos, Nădăștia de Sus, Ohaba Streiului, Sâncrai, Sântămăria de Piatră, Strei, Strei-Săcel, Valea Sângeorgiului"}]},"en":{"tagline":"A steel town in the Strei valley, with Roman baths and two of Transylvania's oldest stone churches.","description":["Călan lies in the Strei valley, between Simeria and Hațeg. First recorded in 1387, it was the Roman settlement of Aquae, known for its warm springs; the Roman baths at Călan remained in use into modern times.","The modern town grew around the ironworks: the foundation of the first blast furnace was laid in 1869, production began in 1870, and after the Second World War Călan became an important centre of Romanian steelmaking, with the Victoria steel plant. The New Town of Călan was built from 1959 on the terrace by Streisângeorgiu.","Its finest monuments are the medieval churches in the town's villages: St George's Church in Streisângeorgiu, built in 1313–1314 according to the inscription in its altar, with murals from 1313–1314, 1409 and 1743 and Roman slabs in its walls, and the church in Strei, from around 1300."],"facts":[{"label":"Population","value":"10,055 (2021 census)"},{"label":"First recorded","value":"1387; in Roman times — Aquae"},{"label":"Industry","value":"ironworks (first blast furnace 1869–1870), later the Victoria steel plant"},{"label":"Landmark","value":"St George's Church, Streisângeorgiu (1313–1314), LMI code HD-II-m-A-03454"},{"label":"Localities","value":"Călan, Streisângeorgiu and the villages of Batiz, Călanu Mic, Grid, Nădăștia de Jos, Nădăștia de Sus, Ohaba Streiului, Sâncrai, Sântămăria de Piatră, Strei, Strei-Săcel, Valea Sângeorgiului"}]}},{"id":"sarmizegetusa","name":"Sarmizegetusa","category":{"ro":"Comună","en":"Commune"},"area":"Țara Hațegului","coords":[45.5153,22.7825],"hasReviews":false,"relatedAreas":["Sarmizegetusa"],"relatedIds":["ulpia-traiana-sarmizegetusa"],"images":["images/sarmizegetusa-amfiteatru.jpg"],"photoCredit":{"author":"Uhserban","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Amfiteatrul_de_la_Ulpia_Traiana_Sarmizegetusa.jpg"},"ro":{"tagline":"Comuna construită peste capitala Daciei romane, Ulpia Traiana Sarmizegetusa.","description":["Sarmizegetusa este o comună din Țara Hațegului, formată din satele Sarmizegetusa (reședința), Breazova, Hobița-Grădiște, Păucinești și Zeicani. Localnicii îi spun și azi Grădiște — de la slavul grad, „cetate”, după ruinele romane — iar numele oficial de Sarmizegetusa l-a primit în 1941.","Satul stă chiar pe locul cetății Ulpia Traiana Sarmizegetusa, capitala Daciei romane întemeiată după 106 d.Hr.: forul, amfiteatrul de circa 5.000 de locuri și templele se vizitează în mijlocul satului, iar Muzeul de Arheologie păstrează descoperirile.","Pe teritoriul comunei se mai află cetatea dacică de la Zeicani și situl unei villa rustica romane la Breazova. Prin Zeicani trece drumul spre pasul Poarta de Fier a Transilvaniei și Banat."],"facts":[{"label":"Populație","value":"1.018 locuitori (recensământ 2021)"},{"label":"Sate","value":"Sarmizegetusa, Breazova, Hobița-Grădiște, Păucinești, Zeicani"},{"label":"Reper","value":"Ulpia Traiana Sarmizegetusa — capitala Daciei romane"},{"label":"Alte situri","value":"cetatea dacică de la Zeicani, villa rustica de la Breazova"}]},"en":{"tagline":"The commune built over the capital of Roman Dacia, Ulpia Traiana Sarmizegetusa.","description":["Sarmizegetusa is a commune in the Hațeg Country, made up of Sarmizegetusa (the seat), Breazova, Hobița-Grădiște, Păucinești and Zeicani. Locals still call it Grădiște — from the Slavic grad, \"fortress\", after the Roman ruins — and it received the official name Sarmizegetusa in 1941.","The village stands right on the site of Ulpia Traiana Sarmizegetusa, the capital of Roman Dacia founded after AD 106: the forum, the amphitheatre with about 5,000 seats and the temples can be visited in the middle of the village, and the Archaeology Museum holds the finds.","The commune also has the Dacian fortress at Zeicani and the site of a Roman villa rustica at Breazova. The road through Zeicani leads to the Iron Gates of Transylvania pass and on to the Banat."],"facts":[{"label":"Population","value":"1,018 (2021 census)"},{"label":"Villages","value":"Sarmizegetusa, Breazova, Hobița-Grădiște, Păucinești, Zeicani"},{"label":"Landmark","value":"Ulpia Traiana Sarmizegetusa — capital of Roman Dacia"},{"label":"Other sites","value":"Dacian fortress at Zeicani, villa rustica at Breazova"}]}},{"id":"densus","name":"Densuș","category":{"ro":"Comună","en":"Commune"},"area":"Țara Hațegului","coords":[45.5802,22.791],"hasReviews":false,"relatedAreas":["Densuș"],"relatedIds":["biserica-densus"],"images":["images/densus-panorama.jpg"],"photoCredit":{"author":"Alexandru Baboș (Albabos)","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Densus.panorama_peste_sat.S.jpg"},"ro":{"tagline":"Sat hațegan cu vedere spre Retezat, celebru pentru biserica de piatră zidită din ruine romane.","description":["Densuș este o comună din nord-vestul Țării Hațegului, formată din satele Densuș (reședința), Criva, Hățăgel, Peșteana, Peștenița, Poieni și Ștei. Dinspre sat, privirea se deschide spre sud, peste depresiune, până la culmile Retezatului.","Faima comunei e Biserica Sf. Nicolae din Densuș, una dintre cele mai vechi biserici din România în care slujba se ține neîntrerupt: ridicată în secolul al XIII-lea din pietre romane aduse de la ruinele din apropiere, are acoperiș din lespezi de piatră și fragmente de pictură din 1443, lucrate de zugravul Ștefan.","La Peșteana, în aceeași comună, se află o altă biserică de piatră din secolul al XIII-lea, „Pogorârea Sfântului Duh”, construită tot cu blocuri romane refolosite. În Densuș se află și bustul lui Ovid Densușianu."],"facts":[{"label":"Populație","value":"1.301 locuitori (recensământ 2021)"},{"label":"Sate","value":"Densuș, Criva, Hățăgel, Peșteana, Peștenița, Poieni, Ștei"},{"label":"Reper","value":"Biserica Sf. Nicolae (sec. XIII), din piatră romană refolosită"},{"label":"Alt monument","value":"Biserica „Pogorârea Sfântului Duh” din Peșteana (sec. XIII), cod LMI HD-II-m-A-03405"}]},"en":{"tagline":"A Hațeg village looking out to the Retezat, famous for its stone church built from Roman ruins.","description":["Densuș is a commune in the north-west of the Hațeg Country, made up of Densuș (the seat), Criva, Hățăgel, Peșteana, Peștenița, Poieni and Ștei. From the village the view opens south across the basin to the Retezat ridges.","The commune is famous for St Nicholas' Church in Densuș, one of the oldest churches in Romania still in continuous use: built in the 13th century from Roman stones taken from nearby ruins, it has a roof of stone slabs and fragments of murals from 1443 by the painter Ștefan.","Peșteana, in the same commune, has another 13th-century stone church, the Descent of the Holy Spirit, also built with reused Roman blocks. Densuș also has a bust of Ovid Densușianu."],"facts":[{"label":"Population","value":"1,301 (2021 census)"},{"label":"Villages","value":"Densuș, Criva, Hățăgel, Peșteana, Peștenița, Poieni, Ștei"},{"label":"Landmark","value":"St Nicholas' Church (13th century), built from reused Roman stone"},{"label":"Other monument","value":"Descent of the Holy Spirit Church, Peșteana (13th century), LMI code HD-II-m-A-03405"}]}},{"id":"rau-de-mori","name":"Râu de Mori","category":{"ro":"Comună","en":"Commune"},"area":"Țara Hațegului","coords":[45.4975,22.8544],"hasReviews":false,"relatedAreas":["Râu de Mori"],"relatedIds":["cetatea-colt","lacul-gura-apelor","traseu-rau-de-mori-varful-retezat","traseu-gura-zlata-lacul-bucura","traseu-culmea-branu-varful-gugu"],"images":["images/rau-de-mori-biserica-candea.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:RauDeMoriHD_(26).JPG"},"ro":{"tagline":"Vechiul centru al cnezilor Cândea, la poalele Retezatului — poartă spre Cetatea Colț și Valea Râului Mare.","description":["Râu de Mori este o comună din sud-vestul Țării Hațegului, la poalele Retezatului, aproape de confluența Râușorului cu Râul Mare. Are 11 sate: Râu de Mori (reședința), Brazi, Clopotiva, Ohaba-Sibișel, Ostrov, Ostrovel, Ostrovu Mic, Sibișel, Suseni, Unciuc și Valea Dâljii.","Satul, atestat în 1359, a fost centrul Cândeștilor — cea mai puternică familie cnezială românească din comitatul Hunedoarei, din care s-au tras mai târziu Kendeffy. În centru se văd ruinele curții lor nobiliare (secolul al XIV-lea), iar în cimitirul din fața lor, biserica „Duminica Tuturor Sfinților”, fosta capelă de curte a Cândeștilor, cu turn-clopotniță masiv.","Mai sus, la Suseni, stau ruinele Cetății Colț și biserica-fortăreață a cnezilor Cândea, iar Valea Râului Mare urcă spre lacul Gura Apelor și intrările în Parcul Național Retezat."],"facts":[{"label":"Populație","value":"2.991 locuitori (recensământ 2021)"},{"label":"Atestare","value":"1359 (possessio Malomwyz)"},{"label":"Monumente","value":"curtea nobiliară a Cândeștilor (cod LMI HD-II-a-A-03428), biserica „Duminica Tuturor Sfinților” (HD-II-m-A-03429)"},{"label":"În apropiere","value":"Cetatea Colț (Suseni), Valea Râului Mare, lacul Gura Apelor"}]},"en":{"tagline":"The old seat of the Cândea knezes at the foot of the Retezat — gateway to Colț Fortress and the Râul Mare valley.","description":["Râu de Mori is a commune in the south-west of the Hațeg Country, at the foot of the Retezat, close to where the Râușor meets the Râul Mare. It has 11 villages: Râu de Mori (the seat), Brazi, Clopotiva, Ohaba-Sibișel, Ostrov, Ostrovel, Ostrovu Mic, Sibișel, Suseni, Unciuc and Valea Dâljii.","First recorded in 1359, the village was the seat of the Cândea family — the most powerful Romanian knez family in Hunedoara county, later known as the Kendeffy. In the centre you can see the ruins of their noble court (14th century), and in the cemetery in front of it the All Saints' Sunday Church, the Cândeas' former court chapel, with a massive bell tower.","Further up, at Suseni, stand the ruins of Colț Fortress and the fortified church of the Cândea knezes, while the Râul Mare valley climbs towards Lake Gura Apelor and the entrances to Retezat National Park."],"facts":[{"label":"Population","value":"2,991 (2021 census)"},{"label":"First recorded","value":"1359 (possessio Malomwyz)"},{"label":"Monuments","value":"Cândea noble court (LMI code HD-II-a-A-03428), All Saints' Sunday Church (HD-II-m-A-03429)"},{"label":"Nearby","value":"Colț Fortress (Suseni), Râul Mare valley, Lake Gura Apelor"}]}},{"id":"ilia","name":"Ilia","category":{"ro":"Comună","en":"Commune"},"area":"Culoarul Mureșului","coords":[45.9344,22.6499],"hasReviews":false,"relatedAreas":["Ilia"],"images":["images/ilia-bastionul-rosu.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:BastionulRosuIlia_(4).JPG"},"ro":{"tagline":"Vechiul târg de pe Mureș unde s-a născut Gabriel Bethlen, principele Transilvaniei.","description":["Ilia este o comună pe malul drept al Mureșului, în vestul județului, formată din satele Ilia (reședința), Bacea, Brâznic, Bretea Mureșană, Cuieș, Dumbrăvița, Săcămaș, Sârbi și Valea Lungă — unele în lunca râului, altele la poalele Munților Poiana Ruscă și Metaliferi. Localitatea apare în documente din 1266, iar în 1350 ca „târgul Ilia”.","După ce turcii au ocupat cetatea Lipovei în 1552, Ilia a devenit cetate de graniță și a fost întărită cu un inel de bastioane. Farkas Bethlen, căruia principele Ștefan Báthory i-a dăruit domeniul, a ridicat în 1582 Bastionul Roșu. În turnul de locuință al cetății s-a născut, în 1580, fiul său Gabriel Bethlen, principe al Transilvaniei între 1613 și 1629.","În 1670 celelalte bastioane și zidurile au fost demolate. Bastionul Roșu, refăcut în stil romantic după 1850, e cunoscut azi drept Casa natală Gabriel Bethlen, iar castelul ridicat în jurul anului 1848 de baronul Bornemisza găzduiește spitalul."],"facts":[{"label":"Populație","value":"3.144 locuitori (recensământ 2021)"},{"label":"Sate","value":"Ilia, Bacea, Brâznic, Bretea Mureșană, Cuieș, Dumbrăvița, Săcămaș, Sârbi, Valea Lungă"},{"label":"Atestare","value":"1266; „târgul Ilia” în 1350"},{"label":"Reper","value":"Bastionul Roșu — Casa natală Gabriel Bethlen (1582), cod LMI HD-II-m-A-03353"}]},"en":{"tagline":"The old market town on the Mureș where Gabriel Bethlen, Prince of Transylvania, was born.","description":["Ilia is a commune on the right bank of the Mureș in the west of the county, made up of Ilia (the seat), Bacea, Brâznic, Bretea Mureșană, Cuieș, Dumbrăvița, Săcămaș, Sârbi and Valea Lungă — some in the river meadow, others at the foot of the Poiana Ruscă and Metaliferi mountains. It appears in records from 1266, and in 1350 as \"the market town of Ilia\".","After the Ottomans took the fortress of Lipova in 1552, Ilia became a border stronghold and was ringed with bastions. Farkas Bethlen, granted the estate by Prince Stephen Báthory, built the Red Bastion in 1582. His son Gabriel Bethlen, Prince of Transylvania from 1613 to 1629, was born in the fortress's residential tower in 1580.","In 1670 the other bastions and the walls were pulled down. The Red Bastion, rebuilt in Romantic style after 1850, is known today as Gabriel Bethlen's birthplace, and the manor built around 1848 by Baron Bornemisza now houses the hospital."],"facts":[{"label":"Population","value":"3,144 (2021 census)"},{"label":"Villages","value":"Ilia, Bacea, Brâznic, Bretea Mureșană, Cuieș, Dumbrăvița, Săcămaș, Sârbi, Valea Lungă"},{"label":"First recorded","value":"1266; \"the market town of Ilia\" in 1350"},{"label":"Landmark","value":"The Red Bastion — Gabriel Bethlen's birthplace (1582), LMI code HD-II-m-A-03353"}]}},{"id":"pui","name":"Pui","category":{"ro":"Comună","en":"Commune"},"area":"Țara Hațegului","coords":[45.515,23.0925],"hasReviews":false,"relatedAreas":["Pui"],"relatedIds":["traseu-pui-rausor","traseu-ohaba-ponor-cioclovina","traseu-gradistea-cetatea-piatra-rosie-cioclovina"],"images":["images/pui-biserica-ponor.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Biserica_din_Ponor_(10).JPG"},"ro":{"tagline":"Comuna de pe valea Streiului, între Țara Hațegului și Munții Șureanu, cu peșteri, rezervații naturale și urme ale omului de Neanderthal.","description":["Pui este o comună din estul Țării Hațegului, formată din satele Pui (reședința), Băiești, Federi, Fizești, Galați, Hobița, Ohaba-Ponor, Ponor, Râu Bărbat, Rușor, Șerel și Uric. Între 1918 și 1950 a fost reședința plășii Pui din județul Hunedoara.","În satul Ohaba-Ponor, în Munții Șureanu, se află Peștera Șura Mare, rezervație naturală cu o intrare monumentală de aproape 40 m înălțime și peste 6,6 km de galerii explorate, care adăpostește a doua mare colonie de lilieci din România, după Huda lui Papară; interiorul e recomandat doar speologilor echipați. Tot la Ohaba-Ponor, locul fosilifer (rezervație de 10 ha) a păstrat unelte musteriene și trei falange atribuite omului de Neanderthal.","Comuna mai are rezervația botanică Fânațele Pui (13 ha), inclusă în Geoparcul Dinozaurilor „Țara Hațegului”, castrul roman de la Râu Bărbat și biserica de piatră „Pogorârea Sfântului Duh” din Ponor, ridicată în 1769. Din satul Pui pornește traseul marcat cu bandă roșie spre baza Salvamont Râușor, în Retezat."],"facts":[{"label":"Populație","value":"3.682 locuitori (recensământ 2021)"},{"label":"Sate","value":"Pui, Băiești, Federi, Fizești, Galați, Hobița, Ohaba-Ponor, Ponor, Râu Bărbat, Rușor, Șerel, Uric"},{"label":"Rezervații naturale","value":"Peștera Șura Mare, Locul fosilifer Ohaba-Ponor (10 ha), Fânațele Pui (13 ha)"},{"label":"Reper","value":"Biserica „Pogorârea Sfântului Duh” din Ponor (1769), cod LMI HD-II-m-B-03416"}]},"en":{"tagline":"A commune in the Strei valley, between the Hațeg Country and the Șureanu Mountains, with caves, nature reserves and traces of Neanderthal man.","description":["Pui is a commune in the east of the Hațeg Country, made up of Pui (the seat), Băiești, Federi, Fizești, Galați, Hobița, Ohaba-Ponor, Ponor, Râu Bărbat, Rușor, Șerel and Uric. Between 1918 and 1950 it was the seat of Pui district in Hunedoara county.","In Ohaba-Ponor, in the Șureanu Mountains, lies Șura Mare Cave, a nature reserve with a monumental entrance almost 40 m high and more than 6.6 km of explored passages, home to Romania's second-largest bat colony after Huda lui Papară; the interior is recommended only for equipped cavers. Also at Ohaba-Ponor, the fossil site (a 10 ha reserve) has yielded Mousterian tools and three finger bones attributed to Neanderthal man.","The commune also has the Fânațele Pui botanical reserve (13 ha), part of the Hațeg Country Dinosaurs Geopark, the Roman fort at Râu Bărbat and the stone Church of the Descent of the Holy Spirit in Ponor, built in 1769. The red-band trail to the Râușor mountain rescue base, in the Retezat, starts from Pui village."],"facts":[{"label":"Population","value":"3,682 (2021 census)"},{"label":"Villages","value":"Pui, Băiești, Federi, Fizești, Galați, Hobița, Ohaba-Ponor, Ponor, Râu Bărbat, Rușor, Șerel, Uric"},{"label":"Nature reserves","value":"Șura Mare Cave, Ohaba-Ponor fossil site (10 ha), Fânațele Pui (13 ha)"},{"label":"Landmark","value":"Church of the Descent of the Holy Spirit in Ponor (1769), LMI code HD-II-m-B-03416"}]}},{"id":"criscior","name":"Crișcior","category":{"ro":"Comună","en":"Commune"},"area":"Munții Metaliferi","coords":[46.1239,22.8644],"hasReviews":false,"relatedAreas":["Crișcior"],"relatedIds":["biserica-criscior"],"images":["images/criscior-biserica-zdrapti.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Zdrapti_3_retusat_2016.jpg"},"ro":{"tagline":"Comuna minieră de lângă Brad, cu o biserică de piatră din secolul al XIV-lea și vechea uzină de aur de la Gurabarza.","description":["Crișcior este o comună de lângă municipiul Brad, în Țara Zarandului, formată din satele Crișcior (reședința), Barza, Valea Arsului și Zdrapți. Sub teritoriul ei se întinde o rețea de galerii și puțuri săpate de-a lungul mai multor secole, în sectoarele miniere Ruda-Barza și Valea Morii.","Minereul era scos la suprafață prin galeria Victor (ulterior „1 Mai”), la 1,2 km sud de Barza, și dus cu funicularul la uzina de preparare de la Gurabarza, construită în 1898, unde s-au extras cantități importante de aur, argint, zinc, cupru și sulf. Linia ferată industrială cu ecartament îngust Brad – Crișcior, din 1906–1907, e clasată monument istoric.","În satul Crișcior se păstrează biserica de piatră „Adormirea Maicii Domnului”, ctitorită la sfârșitul secolului al XIV-lea de cneazul Bâlea și soția sa, cu fragmente importante de pictură murală din epoca fundației, iar în Zdrapți se află o biserică de lemn ridicată în 1852, cu hramul Sfântul Dimitrie."],"facts":[{"label":"Populație","value":"3.389 locuitori (recensământ 2021)"},{"label":"Sate","value":"Crișcior, Barza, Valea Arsului, Zdrapți"},{"label":"Reper","value":"Biserica „Adormirea Maicii Domnului” (sec. XIV–XV), cod LMI HD-II-m-A-03303"},{"label":"Patrimoniu industrial","value":"uzina de preparare Gurabarza (1898); linia ferată îngustă Brad – Crișcior (1906–1907)"}]},"en":{"tagline":"A mining commune next to Brad, with a 14th-century stone church and the old Gurabarza gold-processing plant.","description":["Crișcior is a commune next to the town of Brad, in the Zarand Country, made up of Crișcior (the seat), Barza, Valea Arsului and Zdrapți. Beneath it runs a network of galleries and shafts dug over several centuries, in the Ruda-Barza and Valea Morii mining sectors.","Ore was brought to the surface through the Victor gallery (later \"1 Mai\"), 1.2 km south of Barza, and carried by cableway to the Gurabarza processing plant, built in 1898, where large quantities of gold, silver, zinc, copper and sulphur were extracted. The narrow-gauge industrial railway between Brad and Crișcior, from 1906–1907, is a listed historic monument.","Crișcior village keeps the stone Church of the Dormition, founded in the late 14th century by the local knez Bâlea and his wife, with important fragments of mural painting from that time, while Zdrapți has a wooden church built in 1852 and dedicated to Saint Demetrius."],"facts":[{"label":"Population","value":"3,389 (2021 census)"},{"label":"Villages","value":"Crișcior, Barza, Valea Arsului, Zdrapți"},{"label":"Landmark","value":"Church of the Dormition (14th–15th century), LMI code HD-II-m-A-03303"},{"label":"Industrial heritage","value":"Gurabarza processing plant (1898); Brad – Crișcior narrow-gauge railway (1906–1907)"}]}},{"id":"soimus","name":"Șoimuș","category":{"ro":"Comună","en":"Commune"},"area":"Culoarul Mureșului","coords":[45.9203,22.8761],"hasReviews":false,"relatedAreas":["Șoimuș"],"images":["images/soimus-biserica-de-lemn.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Biserica_de_lemn_din_Soimus.jpg"},"ro":{"tagline":"Comuna de pe valea Mureșului, lângă Deva, cu trei biserici de lemn din secolul al XVIII-lea.","description":["Șoimuș este o comună de pe valea Mureșului, în apropiere de Deva, formată din satele Șoimuș (reședința), Bălata, Bejan, Bejan-Târnăvița, Boholt, Căinelu de Jos, Chișcădaga, Fornădia, Păuliș și Sulighete. Numele satului, ca și cel german Falkendorf, trimite la șoimi.","Comuna păstrează trei biserici de lemn: cea din Șoimuș, cu hramul Sfântul Nicolae, ridicată în 1705 din bârne de stejar — anul e dăltuit în pragul ușii spre naos —, cea din Sulighete, tot cu hramul Sfântul Nicolae, și cea din Căinelu de Jos, cu hramul „Intrarea în Biserică a Maicii Domnului”, ambele din secolul al XVIII-lea.","La Boholt se află un sit arheologic din epoca bronzului, urmele unei villa rustica romane și rezervația naturală Boholt, iar o parte din teritoriul comunei intră în situl Natura 2000 „Râul Mureș între Brănișca și Ilia”."],"facts":[{"label":"Populație","value":"3.386 locuitori (recensământ 2021)"},{"label":"Sate","value":"Șoimuș, Bălata, Bejan, Bejan-Târnăvița, Boholt, Căinelu de Jos, Chișcădaga, Fornădia, Păuliș, Sulighete"},{"label":"Reper","value":"Biserica de lemn „Sfântul Nicolae” din Șoimuș (1705), cod LMI HD-II-m-A-03461"},{"label":"Natură","value":"rezervația Boholt; situl Natura 2000 „Râul Mureș între Brănișca și Ilia”"}]},"en":{"tagline":"A commune in the Mureș valley near Deva, with three 18th-century wooden churches.","description":["Șoimuș is a commune in the Mureș valley, close to Deva, made up of Șoimuș (the seat), Bălata, Bejan, Bejan-Târnăvița, Boholt, Căinelu de Jos, Chișcădaga, Fornădia, Păuliș and Sulighete. The village's name, like its German name Falkendorf, refers to falcons.","The commune keeps three wooden churches: the one in Șoimuș, dedicated to Saint Nicholas and built of oak beams in 1705 — the year is carved into the lintel of the door to the nave —, the one in Sulighete, also dedicated to Saint Nicholas, and the one in Căinelu de Jos, dedicated to the Presentation of the Virgin, both from the 18th century.","Boholt has a Bronze Age archaeological site, the remains of a Roman villa rustica and the Boholt nature reserve, while part of the commune lies within the \"Mureș River between Brănișca and Ilia\" Natura 2000 site."],"facts":[{"label":"Population","value":"3,386 (2021 census)"},{"label":"Villages","value":"Șoimuș, Bălata, Bejan, Bejan-Târnăvița, Boholt, Căinelu de Jos, Chișcădaga, Fornădia, Păuliș, Sulighete"},{"label":"Landmark","value":"Saint Nicholas wooden church in Șoimuș (1705), LMI code HD-II-m-A-03461"},{"label":"Nature","value":"Boholt reserve; \"Mureș River between Brănișca and Ilia\" Natura 2000 site"}]}},{"id":"beriu","name":"Beriu","category":{"ro":"Comună","en":"Commune"},"area":"Munții Orăștiei","coords":[45.7908,23.1908],"hasReviews":false,"relatedAreas":["Beriu"],"images":["images/beriu-biserica.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Biserica_Adormirea_Maicii_Domnuuli_din_Beriu_(1).jpg"},"ro":{"tagline":"Comuna de pe dealurile de la sud de Orăștie, cu Mănăstirea Cucuiș și un castru roman la Orăștioara de Jos.","description":["Beriu este o comună de pe dealurile de la sud de Orăștie, spre Munții Orăștiei, formată din satele Beriu (reședința), Căstău, Cucuiș, Măgureni, Orăștioara de Jos, Poieni, Sereca și Sibișel. Satul Beriu este atestat documentar din 1332, iar în 1673 apare în documente ca Berény.","Pe teritoriul comunei se află Mănăstirea Cucuiș, Cetatea Sibișelului, castrul roman de la Orăștioara de Jos și urmele unei villa rustica romane la Beriu, iar o parte din comună intră în situl Natura 2000 Frumoasa.","Biserica „Adormirea Maicii Domnului” din Beriu a fost ridicată între 1894 și 1897 după planurile arhitectului Nicolae Părău din Orăștie, în locul unei biserici de piatră din secolul al XVIII-lea, distrusă de un incendiu în vara lui 1894. La Căstău și la Beriu, monumente ale eroilor amintesc de localnicii căzuți în războaie."],"facts":[{"label":"Populație","value":"3.281 locuitori (recensământ 2021)"},{"label":"Sate","value":"Beriu, Căstău, Cucuiș, Măgureni, Orăștioara de Jos, Poieni, Sereca, Sibișel"},{"label":"Atestare","value":"1332"},{"label":"Repere","value":"Mănăstirea Cucuiș; castrul roman de la Orăștioara de Jos; Cetatea Sibișelului"}]},"en":{"tagline":"A commune in the hills south of Orăștie, with Cucuiș Monastery and a Roman fort at Orăștioara de Jos.","description":["Beriu is a commune in the hills south of Orăștie, towards the Orăștie Mountains, made up of Beriu (the seat), Căstău, Cucuiș, Măgureni, Orăștioara de Jos, Poieni, Sereca and Sibișel. Beriu village is first recorded in 1332, and in 1673 it appears in documents as Berény.","The commune is home to Cucuiș Monastery, Sibișel Fortress, the Roman fort at Orăștioara de Jos and the remains of a Roman villa rustica at Beriu, and part of it lies within the Frumoasa Natura 2000 site.","Beriu's Church of the Dormition was built between 1894 and 1897 to plans by the Orăștie architect Nicolae Părău, replacing an 18th-century stone church destroyed by fire in the summer of 1894. In Căstău and Beriu, war memorials honour local people who fell in the wars."],"facts":[{"label":"Population","value":"3,281 (2021 census)"},{"label":"Villages","value":"Beriu, Căstău, Cucuiș, Măgureni, Orăștioara de Jos, Poieni, Sereca, Sibișel"},{"label":"First recorded","value":"1332"},{"label":"Landmarks","value":"Cucuiș Monastery; the Roman fort at Orăștioara de Jos; Sibișel Fortress"}]}},{"id":"dobra","name":"Dobra","category":{"ro":"Comună","en":"Commune"},"area":"Culoarul Mureșului","coords":[45.9139,22.5669],"hasReviews":false,"relatedAreas":["Dobra"],"relatedIds":["traseu-hunedoara-dobra"],"images":["images/dobra-biserica-radulesti.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Biserica_de_lemn_din_R%C4%83dule%C8%99ti.jpg"},"ro":{"tagline":"Vechi târg medieval la sud de Mureș, la limita cu Ținutul Pădurenilor, cu biserici de lemn monumente istorice.","description":["Dobra este o comună din vestul județului, formată din 13 sate: Dobra (reședința), Abucea, Bujoru, Făgețel, Lăpușnic, Mihăiești, Panc, Panc-Săliște, Rădulești, Roșcani, Stâncești, Stâncești-Ohaba și Stretea. Satul Dobra se află pe DN68A, la câțiva kilometri sud de Mureș, la limita dintre valea Mureșului și Ținutul Pădurenilor, pe râul Dobra-Bătrâna, care izvorăște din zona vârfului Rusca.","Atestată din 1387, Dobra a fost în Evul Mediu un important centru comercial, cu târguri care atrăgeau negustori din Boemia, Polonia și Germania. În 1721 aici a izbucnit o răscoală țărănească, iar spre sfârșitul secolului al XVIII-lea localitatea a făcut parte din regiunea militară grănicerească; fosta cazarmă a husarilor a devenit mai târziu hotelul „La husariu”.","Comuna are biserici de lemn clasate monumente istorice la Rădulești, Stâncești și Abucea, o biserică de zid din secolul al XIV-lea la Roșcani și una din secolul al XVII-lea la Lăpușnic. Dobra e și capătul traseului marcat cu bandă galbenă care traversează Munții Poiana Ruscă pornind din Hunedoara."],"facts":[{"label":"Populație","value":"3.203 locuitori (recensământ 2021)"},{"label":"Sate","value":"Dobra, Abucea, Bujoru, Făgețel, Lăpușnic, Mihăiești, Panc, Panc-Săliște, Rădulești, Roșcani, Stâncești, Stâncești-Ohaba, Stretea"},{"label":"Atestare","value":"1387"},{"label":"Biserici de lemn monumente","value":"Rădulești (sec. XVIII, cod LMI HD-II-m-A-03426), Stâncești (HD-II-m-B-03451), Abucea"}]},"en":{"tagline":"An old medieval market town south of the Mureș, on the edge of the Pădureni Country, with listed wooden churches.","description":["Dobra is a commune in the west of the county, made up of 13 villages: Dobra (the seat), Abucea, Bujoru, Făgețel, Lăpușnic, Mihăiești, Panc, Panc-Săliște, Rădulești, Roșcani, Stâncești, Stâncești-Ohaba and Stretea. Dobra village lies on the DN68A, a few kilometres south of the Mureș, where the Mureș valley meets the Pădureni Country, on the Dobra-Bătrâna river, which rises near Rusca peak.","First recorded in 1387, Dobra was an important trading centre in the Middle Ages, its fairs drawing merchants from Bohemia, Poland and Germany. A peasant uprising broke out here in 1721, and towards the end of the 18th century the village belonged to the military border region; the former hussar barracks later became the \"La husariu\" hotel.","The commune has listed wooden churches at Rădulești, Stâncești and Abucea, a 14th-century stone church at Roșcani and a 17th-century one at Lăpușnic. Dobra is also the end point of the yellow-band trail that crosses the Poiana Ruscă Mountains from Hunedoara."],"facts":[{"label":"Population","value":"3,203 (2021 census)"},{"label":"Villages","value":"Dobra, Abucea, Bujoru, Făgețel, Lăpușnic, Mihăiești, Panc, Panc-Săliște, Rădulești, Roșcani, Stâncești, Stâncești-Ohaba, Stretea"},{"label":"First recorded","value":"1387"},{"label":"Listed wooden churches","value":"Rădulești (18th century, LMI code HD-II-m-A-03426), Stâncești (HD-II-m-B-03451), Abucea"}]}},{"id":"vata-de-jos","name":"Vața de Jos","category":{"ro":"Comună","en":"Commune"},"area":"Țara Zarandului","coords":[46.1775,22.5967],"hasReviews":false,"relatedAreas":["Vața de Jos"],"relatedIds":["baile-vata-de-jos"],"images":["images/vata-de-jos-cazanesti.jpg"],"photoCredit":{"author":"Nicu Farcaș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Biserica_de_lemn_din_C%C4%83z%C4%83ne%C8%99ti.JPG"},"ro":{"tagline":"Comuna din Zarand cu ape termale, biserici de lemn și satul natal al părintelui Arsenie Boca.","description":["Vața de Jos este o comună din valea Crișului Alb, în nord-vestul județului, formată din 13 sate: Vața de Jos (reședința), Basarabasa, Birtin, Brotuna, Căzănești, Ciungani, Ocișor, Ociu, Prăvăleni, Prihodiște, Tătărăștii de Criș, Târnava de Criș și Vața de Sus. În Vața de Sus s-a născut, la 29 septembrie 1910, părintele Arsenie Boca, înmormântat la Mănăstirea Prislop.","Stațiunea Băile Vața, cu ape termale de 36–38 °C folosite încă de la mijlocul secolului al XIX-lea, a fost redeschisă după mai bine de un deceniu de abandon.","Comuna are numeroase biserici de lemn, între care cele din Căzănești, Basarabasa, Birtin, Ciungani, Ocișor și Ociu sunt monumente istorice. Biserica din Căzănești, din secolul al XVII-lea (după lista monumentelor, al XVIII-lea) și mărită în secolul al XIX-lea, păstrează pictură din 1828, iar cea din Târnava de Criș, din 1824, amintește de luptele din 8 noiembrie 1848, când aici au fost uciși aproximativ 283 de români."],"facts":[{"label":"Populație","value":"3.163 locuitori (recensământ 2021)"},{"label":"Sate","value":"Vața de Jos, Basarabasa, Birtin, Brotuna, Căzănești, Ciungani, Ocișor, Ociu, Prăvăleni, Prihodiște, Tătărăștii de Criș, Târnava de Criș, Vața de Sus"},{"label":"Personalitate","value":"Arsenie Boca (n. 1910, Vața de Sus)"},{"label":"Reper","value":"Biserica de lemn din Căzănești (sec. XVII–XVIII), cod LMI HD-II-m-A-03287"}]},"en":{"tagline":"A Zarand commune with thermal springs, wooden churches and the birthplace of Father Arsenie Boca.","description":["Vața de Jos is a commune in the Crișul Alb valley, in the north-west of the county, made up of 13 villages: Vața de Jos (the seat), Basarabasa, Birtin, Brotuna, Căzănești, Ciungani, Ocișor, Ociu, Prăvăleni, Prihodiște, Tătărăștii de Criș, Târnava de Criș and Vața de Sus. Father Arsenie Boca, buried at Prislop Monastery, was born in Vața de Sus on 29 September 1910.","The Băile Vața spa, with thermal water at 36–38 °C used since the mid-19th century, has reopened after more than a decade of neglect.","The commune has many wooden churches; those in Căzănești, Basarabasa, Birtin, Ciungani, Ocișor and Ociu are listed monuments. The Căzănești church, from the 17th century (18th according to the monuments list) and enlarged in the 19th, keeps paintings from 1828, while the one in Târnava de Criș, from 1824, recalls the fighting of 8 November 1848, when about 283 Romanians were killed here."],"facts":[{"label":"Population","value":"3,163 (2021 census)"},{"label":"Villages","value":"Vața de Jos, Basarabasa, Birtin, Brotuna, Căzănești, Ciungani, Ocișor, Ociu, Prăvăleni, Prihodiște, Tătărăștii de Criș, Târnava de Criș, Vața de Sus"},{"label":"Notable native","value":"Arsenie Boca (born 1910, Vața de Sus)"},{"label":"Landmark","value":"Căzănești wooden church (17th–18th century), LMI code HD-II-m-A-03287"}]}},{"id":"santamaria-orlea","name":"Sântămăria-Orlea","category":{"ro":"Comună","en":"Commune"},"area":"Țara Hațegului","coords":[45.5887,22.971],"hasReviews":false,"relatedAreas":["Sântămăria-Orlea"],"relatedIds":["biserica-santamaria-orlea","castelul-nopcsa-sacel"],"images":["images/santamaria-orlea-castelul-kendeffy.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:SantamariaOrleaHD_(111).JPG"},"ro":{"tagline":"Comuna de lângă Hațeg cu castelul Kendeffy, o biserică de la 1300 și situl fosilifer cu dinozauri de la Sânpetru.","description":["Sântămăria-Orlea este o comună din Țara Hațegului, formată din satele Sântămăria-Orlea (reședința), Balomir, Bărăștii Hațegului, Bucium-Orlea, Ciopeia, Săcel, Sânpetru, Subcetate și Vadu. Satul de reședință, atestat documentar din 1315, se află la 3 km sud-est de Hațeg, pe malul stâng al Streiului.","În sat se află biserica cnezilor Cândea, azi reformată, ridicată spre sfârșitul secolului al XIII-lea, cu picturi murale din 1311 și din jurul anului 1400, și castelul Kendeffy, construit în 1782 de contele Elek Kendeffy și transformat în stil neogotic în a doua jumătate a secolului al XIX-lea, înconjurat de un parc englezesc. Naționalizat după război, castelul a devenit hotel în anii 1980; azi e închis și nu se vizitează.","Pe teritoriul comunei mai sunt castelul familiei Nopcsa de la Săcel, ruinele cetății regale a Hațegului de la Subcetate (secolul al XIII-lea), biserica „Sfântul Gheorghe” din Sânpetru (secolul al XIV-lea) și Locul fosilifer cu dinozauri Sânpetru, rezervație de 5 ha în Geoparcul Dinozaurilor „Țara Hațegului” — aici a făcut Franz Nopcsa, în 1895, primele sale descoperiri paleontologice."],"facts":[{"label":"Populație","value":"3.132 locuitori (recensământ 2021)"},{"label":"Sate","value":"Sântămăria-Orlea, Balomir, Bărăștii Hațegului, Bucium-Orlea, Ciopeia, Săcel, Sânpetru, Subcetate, Vadu"},{"label":"Castelul Kendeffy","value":"1782, fost hotel, azi închis; cod LMI HD-II-a-A-03446"},{"label":"Rezervație","value":"Locul fosilifer cu dinozauri Sânpetru (5 ha)"}]},"en":{"tagline":"A commune near Hațeg with Kendeffy Castle, a church from around 1300 and the Sânpetru dinosaur fossil site.","description":["Sântămăria-Orlea is a commune in the Hațeg Country, made up of Sântămăria-Orlea (the seat), Balomir, Bărăștii Hațegului, Bucium-Orlea, Ciopeia, Săcel, Sânpetru, Subcetate and Vadu. The seat, first recorded in 1315, lies 3 km south-east of Hațeg, on the left bank of the Strei.","The village has the church of the Cândea knezes, now Reformed, built towards the end of the 13th century, with mural paintings from 1311 and from around 1400, and Kendeffy Castle, built in 1782 by Count Elek Kendeffy and remodelled in Gothic Revival style in the second half of the 19th century, set in an English-style park. Nationalised after the war, the castle became a hotel in the 1980s; it is now closed and cannot be visited.","The commune also holds the Nopcsa family manor at Săcel, the ruins of the royal fortress of Hațeg at Subcetate (13th century), Saint George's Church in Sânpetru (14th century) and the Sânpetru dinosaur fossil site, a 5 ha reserve in the Hațeg Country Dinosaurs Geopark — where Franz Nopcsa made his first palaeontological finds in 1895."],"facts":[{"label":"Population","value":"3,132 (2021 census)"},{"label":"Villages","value":"Sântămăria-Orlea, Balomir, Bărăștii Hațegului, Bucium-Orlea, Ciopeia, Săcel, Sânpetru, Subcetate, Vadu"},{"label":"Kendeffy Castle","value":"1782, former hotel, now closed; LMI code HD-II-a-A-03446"},{"label":"Reserve","value":"Sânpetru dinosaur fossil site (5 ha)"}]}},{"id":"baita","name":"Băița","category":{"ro":"Comună","en":"Commune"},"area":"Munții Metaliferi","coords":[46.0306,22.8922],"hasReviews":false,"relatedAreas":["Băița"],"images":["images/baita-magura-craciunesti.jpg"],"photoCredit":{"author":"Oguszt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Krecsunesdi_magura.JPG"},"ro":{"tagline":"Vechi centru minier la poalele Munților Metaliferi, cu o mină de aur exploatată încă din epoca romană.","description":["Băița este o comună din nordul județului, la poalele Munților Metaliferi, formată din satele Băița (reședința), Barbura, Căinelu de Sus, Crăciunești, Fizeș, Hărțăgani, Lunca, Ormindea, Peștera, Săliște și Trestia. Satul Băița se află pe DJ706A, la circa 25 km de Deva și 24 km de Brad, și apare în documente din 1472, sub numele german Pernseyfen.","Bogăția subsolului a făcut din Băița o localitate privilegiată încă de la primele mențiuni. În epoca romană aici a funcționat un important centru minier și administrativ, iar mina de aur era deja exploatată; între dealurile Măgura și Cornet s-au descoperit urmele a 20 de construcții de piatră și cărămidă, conducte de apă, unelte de minerit și două tezaure monetare.","În Băița se află biserica ortodoxă „Buna Vestire”, din 1727, cu pictură din 1797, biserica romano-catolică, din 1780, și Muzeul Textilelor, deschis în 2018, iar la Hărțăgani, pe o colină, biserica de lemn „Buna Vestire”, din 1793. La nord de Crăciunești, calcarele Dealului Măgura sunt rezervație naturală (120 ha), în situl Natura 2000 Măgurile Băiței. Din Băița era scriitorul Mircea Sântimbreanu (1926–1999)."],"facts":[{"label":"Populație","value":"3.113 locuitori (recensământ 2021)"},{"label":"Sate","value":"Băița, Barbura, Căinelu de Sus, Crăciunești, Fizeș, Hărțăgani, Lunca, Ormindea, Peștera, Săliște, Trestia"},{"label":"Atestare","value":"1472 (Pernseyfen)"},{"label":"Natură","value":"rezervația Calcarele din Dealul Măgura (120 ha); situl Natura 2000 Măgurile Băiței"},{"label":"Reper","value":"Biserica de lemn din Hărțăgani (1793), cod LMI HD-II-m-B-03337"}]},"en":{"tagline":"An old mining centre at the foot of the Metaliferi Mountains, with a gold mine worked since Roman times.","description":["Băița is a commune in the north of the county, at the foot of the Metaliferi Mountains, made up of Băița (the seat), Barbura, Căinelu de Sus, Crăciunești, Fizeș, Hărțăgani, Lunca, Ormindea, Peștera, Săliște and Trestia. Băița village lies on the DJ706A, about 25 km from Deva and 24 km from Brad, and appears in records from 1472 under the German name Pernseyfen.","The wealth beneath its ground made Băița a privileged place from its earliest mentions. In Roman times it was an important mining and administrative centre, and its gold mine was already being worked; between the Măgura and Cornet hills, the remains of 20 stone and brick buildings, water pipes, mining tools and two coin hoards have been found.","Băița has the Orthodox Church of the Annunciation, from 1727, with paintings from 1797, the Roman Catholic church, from 1780, and the Textile Museum, opened in 2018, while Hărțăgani has the wooden Church of the Annunciation, from 1793, on a hilltop. North of Crăciunești, the limestone of Măgura Hill is a nature reserve (120 ha) within the Măgurile Băiței Natura 2000 site. The writer Mircea Sântimbreanu (1926–1999) was born in Băița."],"facts":[{"label":"Population","value":"3,113 (2021 census)"},{"label":"Villages","value":"Băița, Barbura, Căinelu de Sus, Crăciunești, Fizeș, Hărțăgani, Lunca, Ormindea, Peștera, Săliște, Trestia"},{"label":"First recorded","value":"1472 (Pernseyfen)"},{"label":"Nature","value":"Măgura Hill limestone reserve (120 ha); Măgurile Băiței Natura 2000 site"},{"label":"Landmark","value":"Hărțăgani wooden church (1793), LMI code HD-II-m-B-03337"}]}},{"id":"vetel","name":"Vețel","category":{"ro":"Comună","en":"Commune"},"area":"Culoarul Mureșului","coords":[45.9047,22.8],"hasReviews":false,"relatedAreas":["Vețel"],"images":["images/vetel-amfiteatrul-micia.jpg"],"photoCredit":{"author":"Saturnian","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Amphitheatre_Micia_01.jpg"},"ro":{"tagline":"Comuna de pe Mureș cu ruinele așezării romane Micia, castelul Gyulay de la Mintia și o biserică medievală la Leșnic.","description":["Vețel este o comună din centrul-vestul județului, pe culoarul Mureșului și în Munții Poiana Ruscă, formată din satele Vețel (reședința), Boia Bârzii, Bretelin, Căoi, Herepeia, Leșnic, Mintia, Muncelu Mare, Muncelu Mic și Runcu Mic. Mintia, Vețel și Leșnic se înșiră de-a lungul Mureșului, iar Muncelu Mic, Muncelu Mare, Runcu Mic și Boia Bârzii sunt sate de munte.","Pe malul stâng al Mureșului, în dreptul termocentralei de la Mintia, se află ruinele Miciei, așezare romană dezvoltată în jurul unui mare castru. Deși avea doar statut rural (pagus), așezarea avea străzi ortogonale, terme, un amfiteatru și un port la Mureș, cu cheiuri din zidărie de piatră.","Biserica „Sfântul Nicolae” din Leșnic, una dintre vechile ctitorii ale cnezilor români din părțile Hunedoarei, a fost construită la sfârșitul secolului al XIV-lea și păstrează pictură murală în naos. La Mintia se află castelul Gyulay Ferenc, cu parcul său, și o biserică reformată din secolul al XVI-lea; vechea biserică de lemn a satului e expusă din 1991 la Muzeul Țăranului Român din București."],"facts":[{"label":"Populație","value":"3.104 locuitori (recensământ 2021)"},{"label":"Sate","value":"Vețel, Boia Bârzii, Bretelin, Căoi, Herepeia, Leșnic, Mintia, Muncelu Mare, Muncelu Mic, Runcu Mic"},{"label":"Micia","value":"castru și așezare romană — amfiteatru, terme, port la Mureș"},{"label":"Reper","value":"Biserica „Sfântul Nicolae” din Leșnic (sfârșitul sec. XIV), cod LMI HD-II-m-A-03359"}]},"en":{"tagline":"A Mureș commune with the ruins of the Roman settlement of Micia, the Gyulay manor at Mintia and a medieval church at Leșnic.","description":["Vețel is a commune in the centre-west of the county, along the Mureș corridor and into the Poiana Ruscă Mountains, made up of Vețel (the seat), Boia Bârzii, Bretelin, Căoi, Herepeia, Leșnic, Mintia, Muncelu Mare, Muncelu Mic and Runcu Mic. Mintia, Vețel and Leșnic line the Mureș, while Muncelu Mic, Muncelu Mare, Runcu Mic and Boia Bârzii are mountain villages.","On the left bank of the Mureș, opposite the Mintia power station, lie the ruins of Micia, a Roman settlement that grew up around a large fort. Although only a rural settlement (pagus), it had a grid of streets, baths, an amphitheatre and a river port on the Mureș with stone quays.","Saint Nicholas Church in Leșnic, one of the old foundations of the Romanian knezes of the Hunedoara region, was built in the late 14th century and keeps mural paintings in the nave. Mintia has the Gyulay Ferenc manor with its park and a 16th-century Reformed church; the village's old wooden church has been on display at the National Museum of the Romanian Peasant in Bucharest since 1991."],"facts":[{"label":"Population","value":"3,104 (2021 census)"},{"label":"Villages","value":"Vețel, Boia Bârzii, Bretelin, Căoi, Herepeia, Leșnic, Mintia, Muncelu Mare, Muncelu Mic, Runcu Mic"},{"label":"Micia","value":"Roman fort and settlement — amphitheatre, baths, river port"},{"label":"Landmark","value":"Saint Nicholas Church in Leșnic (late 14th century), LMI code HD-II-m-A-03359"}]}},{"id":"harau","name":"Hărău","category":{"ro":"Comună","en":"Commune"},"area":"Culoarul Mureșului","coords":[45.9006,22.9569],"hasReviews":false,"relatedAreas":["Hărău"],"relatedIds":["vila-castelul-maria-banpotoc"],"images":["images/harau-biserica-barsau.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Biserica_Sf%C3%A2ntul_Nicolae_din_B%C3%A2rs%C4%83u_(4).jpg"},"ro":{"tagline":"Comună liniștită din apropiere de Deva, cu biserici din secolele XVI–XVIII, izvoare minerale carbogazoase și Vila Castelul Maria din Bănpotoc.","description":["Hărău este o comună din județul Hunedoara, în Transilvania, aflată la câțiva kilometri de Deva, pe culoarul Mureșului. Din ea fac parte satele Hărău (reședința), Bănpotoc, Bârsău și Chimindia. Este un colț de sat tradițional, potrivit pentru o escapadă liniștită în apropierea municipiului.","Satele păstrează câteva biserici vechi, declarate monumente istorice: biserica „Sfântul Nicolae” din Bârsău, din secolul al XVI-lea, biserica „Sfântul Dumitru” din Hărău, din secolul al XVIII-lea, și biserica „Cuvioasa Paraschiva” din Chimindia, din secolul al XVI-lea. La Chimindia și la Bănpotoc există izvoare de apă minerală carbogazoasă.","În Bănpotoc se află Vila Castelul Maria, o clădire în stil de mic castel cu turn, înconjurată de o grădină mare, care primește oaspeți pentru cazare, saună și evenimente de familie."],"facts":[{"label":"Populație","value":"2.026 locuitori (recensământ 2021)"},{"label":"Sate","value":"Hărău, Bănpotoc, Bârsău, Chimindia"},{"label":"Repere","value":"biserica „Sfântul Nicolae” din Bârsău (sec. XVI), biserica „Sfântul Dumitru” din Hărău (sec. XVIII), biserica „Cuvioasa Paraschiva” din Chimindia (sec. XVI)"},{"label":"Natură","value":"izvoare minerale carbogazoase la Chimindia și Bănpotoc"},{"label":"Cazare","value":"Vila Castelul Maria, Bănpotoc nr. 20"}]},"en":{"tagline":"A quiet commune near Deva, with 16th–18th-century churches, carbonated mineral springs and the Castelul Maria Villa in Bănpotoc.","description":["Hărău is a commune in Hunedoara County, in Transylvania, a few kilometres from Deva, along the Mureș corridor. It is made up of the villages of Hărău (the seat), Bănpotoc, Bârsău and Chimindia. It is a traditional village corner, well suited to a quiet getaway close to the city.","The villages keep a few old churches listed as historic monuments: Saint Nicholas Church in Bârsău, from the 16th century, Saint Demetrius Church in Hărău, from the 18th century, and Saint Paraskeva Church in Chimindia, from the 16th century. Chimindia and Bănpotoc have carbonated mineral water springs.","Bănpotoc is home to Castelul Maria Villa, a building designed as a small castle with a tower, set in a large garden, which welcomes guests for accommodation, a sauna and family events."],"facts":[{"label":"Population","value":"2,026 (2021 census)"},{"label":"Villages","value":"Hărău, Bănpotoc, Bârsău, Chimindia"},{"label":"Landmarks","value":"Saint Nicholas Church in Bârsău (16th c.), Saint Demetrius Church in Hărău (18th c.), Saint Paraskeva Church in Chimindia (16th c.)"},{"label":"Nature","value":"carbonated mineral springs at Chimindia and Bănpotoc"},{"label":"Stay","value":"Castelul Maria Villa, Bănpotoc no. 20"}]}},{"id":"bosorod","name":"Boșorod","category":{"ro":"Comună","en":"Commune"},"area":"Zona cetăților dacice","coords":[45.6261,23.1289],"hasReviews":false,"relatedAreas":["Boșorod"],"relatedIds":["pestera-cioclovina","cetatea-piatra-rosie"],"images":["images/cetatea-piatra-rosie-zid.jpg"],"photoCredit":{"author":"Korinna","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cetatea_Piatra_Rosie_WP_20170604_15_56_36_Pro_highres.jpg"},"ro":{"tagline":"Comuna de la poalele Munților Orăștiei, cu cetatea dacică Piatra Roșie (UNESCO), Peștera Cioclovina Uscată și castre romane.","description":["Boșorod este o comună din sud-vestul județului Hunedoara, formată din satele Boșorod (reședința), Alun, Bobaia, Chitid, Cioclovina, Luncani, Prihodiște, Târsa și Ursici. O parte din teritoriul ei se află în Parcul Natural Grădiștea Muncelului–Cioclovina.","Pe dealul de la Luncani se află cetatea dacică Piatra Roșie, parte din cetățile dacice din Munții Orăștiei înscrise în patrimoniul mondial UNESCO. Tot aici sunt castrele romane de la Luncani și Chitid, villa rustica de la Chitid și biserica de lemn „Adormirea Maicii Domnului” din Luncani, construită în 1803.","La Cioclovina se află peștera „Cioclovina Uscată” și rezervația naturală „Ponorici–Cioclovina”, un complex carstic cu peșteri, ponoare și chei. La Bobaia este cunoscută „Fântâna cu leacuri”."],"facts":[{"label":"Populație","value":"1.781 locuitori (recensământ 2021)"},{"label":"Sate","value":"Boșorod, Alun, Bobaia, Chitid, Cioclovina, Luncani, Prihodiște, Târsa, Ursici"},{"label":"Repere","value":"cetatea dacică Piatra Roșie (UNESCO), peștera Cioclovina Uscată, castrele romane Luncani și Chitid"},{"label":"Arii protejate","value":"Parcul Natural Grădiștea Muncelului–Cioclovina, rezervația „Ponorici–Cioclovina”"}]},"en":{"tagline":"A commune at the foot of the Orăștie Mountains, with the Dacian fortress of Piatra Roșie (UNESCO), the Cioclovina Uscată Cave and Roman forts.","description":["Boșorod is a commune in the south-west of Hunedoara County, made up of the villages of Boșorod (the seat), Alun, Bobaia, Chitid, Cioclovina, Luncani, Prihodiște, Târsa and Ursici. Part of its territory lies within the Grădiștea Muncelului–Cioclovina Nature Park.","On the hill at Luncani stands the Dacian fortress of Piatra Roșie, one of the Dacian fortresses of the Orăștie Mountains on the UNESCO World Heritage List. The commune also has the Roman forts at Luncani and Chitid, the villa rustica at Chitid and the wooden church of the Dormition of the Mother of God at Luncani, built in 1803.","At Cioclovina are the Cioclovina Uscată cave and the Ponorici–Cioclovina nature reserve, a karst complex of caves, sinkholes and gorges. Bobaia is known for its “healing spring”."],"facts":[{"label":"Population","value":"1,781 (2021 census)"},{"label":"Villages","value":"Boșorod, Alun, Bobaia, Chitid, Cioclovina, Luncani, Prihodiște, Târsa, Ursici"},{"label":"Landmarks","value":"Piatra Roșie Dacian fortress (UNESCO), Cioclovina Uscată cave, Roman forts at Luncani and Chitid"},{"label":"Protected areas","value":"Grădiștea Muncelului–Cioclovina Nature Park, “Ponorici–Cioclovina” reserve"}]}},{"id":"banita","name":"Bănița","category":{"ro":"Comună","en":"Commune"},"area":"Valea Jiului","coords":[45.4458,23.2611],"hasReviews":false,"relatedAreas":["Bănița"],"relatedIds":["pestera-bolii"],"images":["images/cheile-crivadiei.jpg"],"photoCredit":{"author":"Zsolt deak","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Turn_de_cetate_(ruine).JPG"},"ro":{"tagline":"Comuna de la intrarea în Valea Jiului, cu fortăreața dacică și castrul roman de la Bănița, Cheile Băniței, Peștera Bolii și Cheile Crivadiei.","description":["Bănița este o comună de munte din sudul județului Hunedoara, aflată la circa 756 m altitudine, formată din satele Bănița (reședința), Crivadia și Merișor. Drumul național DN66 și calea ferată Simeria–Petroșani trec prin Cheile Băniței, la intrarea în Valea Jiului.","Pe teritoriul comunei se află fortăreața dacică de la Bănița, inclusă în patrimoniul mondial UNESCO, și castrul roman din apropiere. La Crivadia se păstrează ruinele unui turn de cetate medieval, lângă rezervația naturală „Cheile Crivadiei”.","Peștera Bolii, o peșteră-râu amenajată cu iluminat electric, pe râul Galbina, este rezervație naturală și o oprire frecventă pentru turiști. Zona se leagă de Parcul Natural Grădiștea Muncelului–Cioclovina și de traseul tematic spre cetatea dacică."],"facts":[{"label":"Populație","value":"1.092 locuitori (recensământ 2021)"},{"label":"Sate","value":"Bănița, Crivadia, Merișor"},{"label":"Repere","value":"fortăreața dacică și castrul roman de la Bănița, turnul de cetate din Crivadia, Cheile Băniței"},{"label":"Rezervații","value":"Peștera Bolii (10 ha), Cheile Crivadiei (10 ha)"}]},"en":{"tagline":"The commune at the gateway to the Jiu Valley, with the Dacian fortress and Roman fort at Bănița, the Bănița Gorge, Bolii Cave and the Crivadia Gorge.","description":["Bănița is a mountain commune in the south of Hunedoara County, at about 756 m altitude, made up of the villages of Bănița (the seat), Crivadia and Merișor. National road DN66 and the Simeria–Petroșani railway run through the Bănița Gorge, at the entrance to the Jiu Valley.","The commune has the Dacian fortress of Bănița, part of the UNESCO World Heritage List, and a nearby Roman fort. At Crivadia stand the ruins of a medieval fortress tower, next to the “Crivadia Gorge” nature reserve.","Bolii Cave, a river cave lit by electric lighting on the Galbina river, is a nature reserve and a frequent stop for visitors. The area connects to the Grădiștea Muncelului–Cioclovina Nature Park and to the themed trail up to the Dacian fortress."],"facts":[{"label":"Population","value":"1,092 (2021 census)"},{"label":"Villages","value":"Bănița, Crivadia, Merișor"},{"label":"Landmarks","value":"Dacian fortress and Roman fort at Bănița, the Crivadia fortress tower, the Bănița Gorge"},{"label":"Reserves","value":"Bolii Cave (10 ha), Crivadia Gorge (10 ha)"}]}},{"id":"ribita","name":"Ribița","category":{"ro":"Comună","en":"Commune"},"area":"Munții Metaliferi","coords":[46.1833,22.7667],"hasReviews":false,"relatedAreas":["Ribița"],"relatedIds":["casa-memoriala-crisan"],"images":["images/casa-memoriala-crisan.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:CasaNatalaCrisan_(22).jpg"},"ro":{"tagline":"Comună din Munții Metaliferi, cu casa memorială a lui Crișan, biserici vechi de lemn și de zid și Cheile Ribiciorei.","description":["Ribița este o comună din nord-vestul județului Hunedoara, în Munții Metaliferi, formată din satele Ribița (reședința), Crișan, Dumbrava de Jos, Dumbrava de Sus, Ribicioara și Uibărești. Este o zonă de sate de munte, la nord de Brad.","În satul Crișan (fost Vaca) se află casa memorială a lui Gheorghe Crișan, unul dintre conducătorii răscoalei din 1784–1785, cu bustul lui. Comuna păstrează mai multe biserici monument istoric: biserica „Sfântul Nicolae” din Ribița (1417), bisericile de lemn din Dumbrava de Jos, Dumbrava de Sus (1844) și Ribicioara (1763) și biserica „Sfântul Nicolae” din Uibărești.","Rezervația naturală „Cheile Ribiciorei și Uibăreștilor” (20 ha) adăpostește și Peștera Cizmei."],"facts":[{"label":"Populație","value":"1.170 locuitori (recensământ 2021)"},{"label":"Sate","value":"Ribița, Crișan, Dumbrava de Jos, Dumbrava de Sus, Ribicioara, Uibărești"},{"label":"Repere","value":"casa memorială Crișan, biserica „Sfântul Nicolae” din Ribița (1417), bisericile de lemn din Ribicioara (1763) și Dumbrava de Sus (1844)"},{"label":"Natură","value":"rezervația „Cheile Ribiciorei și Uibăreștilor” (20 ha), Peștera Cizmei"}]},"en":{"tagline":"A commune in the Metaliferi Mountains, with Crișan's memorial house, old wooden and stone churches and the Ribicioara Gorge.","description":["Ribița is a commune in the north-west of Hunedoara County, in the Metaliferi Mountains, made up of the villages of Ribița (the seat), Crișan, Dumbrava de Jos, Dumbrava de Sus, Ribicioara and Uibărești. It is a mountain-village area north of Brad.","In the village of Crișan (formerly Vaca) stands the memorial house of Gheorghe Crișan, one of the leaders of the 1784–1785 uprising, with his bust. The commune keeps several listed churches: Saint Nicholas Church in Ribița (1417), the wooden churches of Dumbrava de Jos, Dumbrava de Sus (1844) and Ribicioara (1763) and Saint Nicholas Church in Uibărești.","The “Ribicioara and Uibărești Gorges” nature reserve (20 ha) also shelters the Cizmei Cave."],"facts":[{"label":"Population","value":"1,170 (2021 census)"},{"label":"Villages","value":"Ribița, Crișan, Dumbrava de Jos, Dumbrava de Sus, Ribicioara, Uibărești"},{"label":"Landmarks","value":"Crișan memorial house, Saint Nicholas Church in Ribița (1417), wooden churches in Ribicioara (1763) and Dumbrava de Sus (1844)"},{"label":"Nature","value":"“Ribicioara and Uibărești Gorges” reserve (20 ha), Cizmei Cave"}]}},{"id":"bulzestii-de-sus","name":"Bulzeștii de Sus","category":{"ro":"Comună","en":"Commune"},"area":"Țara Zarandului","coords":[46.3008,22.7833],"hasReviews":false,"relatedAreas":["Bulzeștii de Sus"],"relatedIds":["podul-natural-grohot"],"images":["images/bulzestii-biserica-tomnatec.jpg"],"photoCredit":{"author":"Dobrei Florin (încărcat de Țetcu Mircea Rareș)","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Tomnatecu_de_Sus_church_3.jpg"},"ro":{"tagline":"Comună rară din Țara Zarandului, cu nouă sate risipite pe munte, biserici de lemn monument istoric și Podul natural de la Grohot.","description":["Bulzeștii de Sus este o comună din nord-vestul județului Hunedoara, în Țara Zarandului, formată din nouă sate: Bulzeștii de Jos, Bulzeștii de Sus (reședința), Giurgești, Grohot, Păulești, Rusești, Stănculești, Ticera și Tomnatec. Satele sunt împrăștiate pe văile și dealurile Munților Metaliferi.","Comuna are două biserici de lemn monument istoric: biserica „Sfântul Ioan Gură de Aur” din Bulzeștii de Sus (1853) și biserica „Buna Vestire” din Tomnatec, din secolul al XVIII-lea.","La Grohot, pe valea Uibăreștilor, se află Podul natural de la Grohot, monument al naturii ocrotit pentru podul de calcar și vegetația din jur."],"facts":[{"label":"Sate","value":"Bulzeștii de Jos, Bulzeștii de Sus, Giurgești, Grohot, Păulești, Rusești, Stănculești, Ticera, Tomnatec"},{"label":"Repere","value":"biserica de lemn din Bulzeștii de Sus (1853), biserica de lemn „Buna Vestire” din Tomnatec (sec. XVIII)"},{"label":"Natură","value":"Podul natural de la Grohot, valea Uibăreștilor"}]},"en":{"tagline":"A sparsely populated commune in Zarand Country, with nine villages scattered over the mountains, listed wooden churches and the Grohot Natural Bridge.","description":["Bulzeștii de Sus is a commune in the north-west of Hunedoara County, in Zarand Country, made up of nine villages: Bulzeștii de Jos, Bulzeștii de Sus (the seat), Giurgești, Grohot, Păulești, Rusești, Stănculești, Ticera and Tomnatec. The villages are scattered over the valleys and hills of the Metaliferi Mountains.","The commune has two listed wooden churches: Saint John Chrysostom Church in Bulzeștii de Sus (1853) and the Annunciation Church in Tomnatec, from the 18th century.","At Grohot, in the Uibărești valley, lies the Grohot Natural Bridge, a nature monument protected for its limestone bridge and the surrounding vegetation."],"facts":[{"label":"Villages","value":"Bulzeștii de Jos, Bulzeștii de Sus, Giurgești, Grohot, Păulești, Rusești, Stănculești, Ticera, Tomnatec"},{"label":"Landmarks","value":"wooden church in Bulzeștii de Sus (1853), “Annunciation” wooden church in Tomnatec (18th c.)"},{"label":"Nature","value":"Grohot Natural Bridge, the Uibărești valley"}]}},{"id":"lunca-cernii-de-jos","name":"Lunca Cernii de Jos","category":{"ro":"Comună","en":"Commune"},"area":"Poiana Ruscă","coords":[45.6383,22.6147],"hasReviews":false,"relatedAreas":["Lunca Cernii de Jos"],"relatedIds":["cheile-cernei"],"images":["images/cheile-cernei.jpg"],"photoCredit":{"author":"Nicu Farcaș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Cheile_Cernei.JPG"},"ro":{"tagline":"Comună de munte din Poiana Ruscă, pe valea Cernei, cu Cheile Cernei și opt sate risipite în Ținutul Pădurenilor.","description":["Lunca Cernii de Jos este o comună din Munții Poiana Ruscă, formată din satele Lunca Cernii de Jos (reședința), Ciumița, Fântâna, Gura Bordului, Lunca Cernii de Sus, Meria, Negoiu și Valea Babii. Este una dintre cele mai întinse și mai puțin populate comune ale județului, cu pădure, văi și sate de munte.","Rezervația naturală „Cheile Cernei” (2 ha) este un defileu săpat de râul Cerna în șisturile cristaline ale Poienii Ruscă, inclus în rețeaua Natura 2000. Comuna se află și în situl „Ținutul Pădurenilor”, zona locuită de pădureni, cu tradiții păstrate în satele de munte."],"facts":[{"label":"Populație","value":"758 locuitori (recensământ 2021)"},{"label":"Sate","value":"Lunca Cernii de Jos, Ciumița, Fântâna, Gura Bordului, Lunca Cernii de Sus, Meria, Negoiu, Valea Babii"},{"label":"Natură","value":"rezervația „Cheile Cernei” (2 ha), siturile Natura 2000 Cheile Cernei și Ținutul Pădurenilor"}]},"en":{"tagline":"A mountain commune in the Poiana Ruscă range, on the Cerna valley, with the Cerna Gorge and eight villages scattered through the Pădureni Land.","description":["Lunca Cernii de Jos is a commune in the Poiana Ruscă Mountains, made up of the villages of Lunca Cernii de Jos (the seat), Ciumița, Fântâna, Gura Bordului, Lunca Cernii de Sus, Meria, Negoiu and Valea Babii. It is one of the largest and least populated communes in the county, with forests, valleys and mountain villages.","The “Cerna Gorge” nature reserve (2 ha) is a gorge cut by the Cerna river through the crystalline schists of Poiana Ruscă, part of the Natura 2000 network. The commune also lies in the “Pădureni Land” site, home to the pădureni and their traditions kept alive in the mountain villages."],"facts":[{"label":"Population","value":"758 (2021 census)"},{"label":"Villages","value":"Lunca Cernii de Jos, Ciumița, Fântâna, Gura Bordului, Lunca Cernii de Sus, Meria, Negoiu, Valea Babii"},{"label":"Nature","value":"“Cerna Gorge” reserve (2 ha), Natura 2000 sites Cheile Cernei and Ținutul Pădurenilor"}]}},{"id":"baia-de-cris","name":"Baia de Criș","category":{"ro":"Comună","en":"Commune"},"area":"Țara Zarandului","coords":[46.1747,22.7153],"hasReviews":false,"relatedAreas":["Baia de Criș"],"relatedIds":["panteonul-motilor-tebea"],"images":["images/panteonul-motilor-tebea.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Tebea_2011.21.jpg"},"ro":{"tagline":"Comună din Țara Zarandului, pe valea Crișului Alb, cu Țebea, Gorunul lui Horea, mormântul lui Avram Iancu și biserici vechi de lemn.","description":["Baia de Criș este o comună din nord-vestul județului Hunedoara, în Țara Zarandului, formată din satele Baia de Criș (reședința), Baldovin, Căraci, Cărăstău, Lunca, Rișca, Rișculița, Țebea și Văleni. A fost reședința Prefecturii Zarandului, condusă de Ioan Buteanu în Revoluția de la 1848.","În satul Țebea se află complexul memorial cu mormântul lui Avram Iancu și Gorunul lui Horea, loc de pelerinaj național. La Baia de Criș sunt casa memorială Avram Iancu și un obelisc inaugurat în 1972, la 100 de ani de la moartea lui, precum și o biserică franciscană din secolul al XV-lea.","Comuna păstrează și bisericile de lemn monument istoric din Căraci (secolul al XVIII-lea) și Lunca (secolul al XVII-lea). Zona face parte din situl Natura 2000 „Munții Metaliferi”."],"facts":[{"label":"Populație","value":"2.176 locuitori (recensământ 2021)"},{"label":"Sate","value":"Baia de Criș, Baldovin, Căraci, Cărăstău, Lunca, Rișca, Rișculița, Țebea, Văleni"},{"label":"Repere","value":"complexul memorial Țebea (Avram Iancu, Gorunul lui Horea), casa memorială Avram Iancu, biserica franciscană (sec. XV)"},{"label":"Biserici de lemn","value":"Căraci (sec. XVIII), Lunca (sec. XVII)"}]},"en":{"tagline":"A commune in Zarand Country, on the Crișul Alb valley, with Țebea, Horea's Oak, Avram Iancu's grave and old wooden churches.","description":["Baia de Criș is a commune in the north-west of Hunedoara County, in Zarand Country, made up of the villages of Baia de Criș (the seat), Baldovin, Căraci, Cărăstău, Lunca, Rișca, Rișculița, Țebea and Văleni. It was the seat of the Zarand prefecture, led by Ioan Buteanu during the 1848 Revolution.","In the village of Țebea stands the memorial complex with Avram Iancu's grave and Horea's Oak, a national place of pilgrimage. Baia de Criș has the Avram Iancu memorial house and an obelisk unveiled in 1972, a hundred years after his death, as well as a 15th-century Franciscan church.","The commune also keeps listed wooden churches at Căraci (18th century) and Lunca (17th century). The area is part of the Natura 2000 site “Metaliferi Mountains”."],"facts":[{"label":"Population","value":"2,176 (2021 census)"},{"label":"Villages","value":"Baia de Criș, Baldovin, Căraci, Cărăstău, Lunca, Rișca, Rișculița, Țebea, Văleni"},{"label":"Landmarks","value":"Țebea memorial complex (Avram Iancu, Horea's Oak), Avram Iancu memorial house, Franciscan church (15th c.)"},{"label":"Wooden churches","value":"Căraci (18th c.), Lunca (17th c.)"}]}},{"id":"salasu-de-sus","name":"Sălașu de Sus","category":{"ro":"Comună","en":"Commune"},"area":"Țara Hațegului","coords":[45.51,22.9547],"hasReviews":false,"relatedAreas":["Sălașu de Sus"],"relatedIds":["cetatea-malaiesti","cascada-lolaia"],"images":["images/cetatea-malaiesti.jpg"],"photoCredit":{"author":"Raimond Spekking","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Malaistii_fortress,_Romania-9103.jpg"},"ro":{"tagline":"Comuna de la poalele Retezatului, cu Cetatea Mălăiești, biserici din secolul al XV-lea, curtea cnezilor Cândreș și valea Nucșoarei.","description":["Sălașu de Sus este o comună din Țara Hațegului, la poalele Munților Retezat, formată din satele Sălașu de Sus (reședința), Coroiești, Mălăiești, Nucșoara, Ohaba de sub Piatră, Paroș, Peștera, Râu Alb, Râu Mic, Sălașu de Jos și Zăvoi. Este o comună întinsă, cu o bună parte din teritoriu în zona montană.","La Mălăiești se află Cetatea Mălăiești, o cetate nobiliară din secolul al XIV-lea. La Sălașu de Sus se păstrează biserica „Sfinții Atanasie și Chiril” și curtea cnezilor Cândreș (secolul al XV-lea), iar la Paroș și Râu Alb sunt alte biserici medievale. Valea Nucșoarei duce spre Retezat și spre cascada Lolaia.","Printre ariile protejate se numără rezervația „Fânațele cu narcise Nucșoara” (20 ha)."],"facts":[{"label":"Populație","value":"2.142 locuitori (recensământ 2021)"},{"label":"Sate","value":"Sălașu de Sus, Coroiești, Mălăiești, Nucșoara, Ohaba de sub Piatră, Paroș, Peștera, Râu Alb, Râu Mic, Sălașu de Jos, Zăvoi"},{"label":"Repere","value":"Cetatea Mălăiești (sec. XIV), curtea cnezilor Cândreș (sec. XV), biserici medievale la Sălașu de Sus, Paroș și Râu Alb"},{"label":"Natură","value":"valea Nucșoarei, cascada Lolaia, rezervația „Fânațele cu narcise Nucșoara” (20 ha)"}]},"en":{"tagline":"A commune at the foot of the Retezat Mountains, with Mălăiești Fortress, 15th-century churches, the Cândreș knezes' court and the Nucșoara valley.","description":["Sălașu de Sus is a commune in Hațeg Country, at the foot of the Retezat Mountains, made up of the villages of Sălașu de Sus (the seat), Coroiești, Mălăiești, Nucșoara, Ohaba de sub Piatră, Paroș, Peștera, Râu Alb, Râu Mic, Sălașu de Jos and Zăvoi. It is a large commune, with much of its territory in the mountains.","At Mălăiești stands Mălăiești Fortress, a 14th-century noble stronghold. Sălașu de Sus keeps the Saints Athanasius and Cyril church and the court of the Cândreș knezes (15th century), while Paroș and Râu Alb have other medieval churches. The Nucșoara valley leads to the Retezat and to the Lolaia waterfall.","Protected areas include the “Nucșoara Narcissus Meadows” reserve (20 ha)."],"facts":[{"label":"Population","value":"2,142 (2021 census)"},{"label":"Villages","value":"Sălașu de Sus, Coroiești, Mălăiești, Nucșoara, Ohaba de sub Piatră, Paroș, Peștera, Râu Alb, Râu Mic, Sălașu de Jos, Zăvoi"},{"label":"Landmarks","value":"Mălăiești Fortress (14th c.), Cândreș knezes' court (15th c.), medieval churches at Sălașu de Sus, Paroș and Râu Alb"},{"label":"Nature","value":"Nucșoara valley, Lolaia waterfall, “Nucșoara Narcissus Meadows” reserve (20 ha)"}]}},{"id":"orastioara-de-sus","name":"Orăștioara de Sus","category":{"ro":"Comună","en":"Commune"},"area":"Zona cetăților dacice","coords":[45.7333,23.1667],"hasReviews":false,"relatedAreas":["Orăștioara de Sus"],"relatedIds":["sarmizegetusa-regia","cetatea-costesti-blidaru","cetatea-costesti-cetatuie","traseu-costesti-sarmizegetusa-regia-varful-godeanu","traseu-costesti-cetatea-blidaru-varful-godeanu","traseu-cetatea-fetele-albe","traseu-gradistea-cetatea-piatra-rosie-cioclovina"],"images":["images/cetatea-blidaru.jpg"],"photoCredit":{"author":"Oroles","license":"Domeniu public","source":"https://commons.wikimedia.org/wiki/File:Cetatea_Blidaru.JPG"},"ro":{"tagline":"Comuna din inima cetăților dacice, cu Sarmizegetusa Regia, Costești–Blidaru, Costești–Cetățuie și Fețele Albe, în patrimoniul UNESCO.","description":["Orăștioara de Sus este o comună din Munții Orăștiei, formată din satele Orăștioara de Sus (reședința), Bucium, Costești, Costești-Deal, Grădiștea de Munte, Ludeștii de Jos, Ludeștii de Sus și Ocolișu Mic. Pe teritoriul ei se află o mare parte din cetățile dacice din Munții Orăștiei, înscrise în patrimoniul mondial UNESCO.","La Grădiștea de Munte se află așezarea dacică de la Sarmizegetusa Regia, capitala regatului dac, iar în zona Fețele Albe sunt alte vestigii dacice. La Costești sunt cetățile dacice Costești–Blidaru și Costești–Cetățuie, iar la Bucium, Grădiștea de Munte și Costești-Deal se păstrează castre romane și fortificații dacice.","Comuna face parte din Parcul Natural Grădiștea Muncelului–Cioclovina. Bisericile din Orăștioara de Sus (1794), Bucium (1892–1900) și Ludeștii de Jos (1902) completează patrimoniul local."],"facts":[{"label":"Populație","value":"1.910 locuitori (recensământ 2021)"},{"label":"Sate","value":"Orăștioara de Sus, Bucium, Costești, Costești-Deal, Grădiștea de Munte, Ludeștii de Jos, Ludeștii de Sus, Ocolișu Mic"},{"label":"Repere","value":"Sarmizegetusa Regia, cetățile Costești–Blidaru și Costești–Cetățuie, Fețele Albe (UNESCO)"},{"label":"Arii protejate","value":"Parcul Natural Grădiștea Muncelului–Cioclovina, situl Natura 2000 „Frumoasa”"}]},"en":{"tagline":"The commune at the heart of the Dacian fortresses, with Sarmizegetusa Regia, Costești–Blidaru, Costești–Cetățuie and Fețele Albe, all UNESCO-listed.","description":["Orăștioara de Sus is a commune in the Orăștie Mountains, made up of the villages of Orăștioara de Sus (the seat), Bucium, Costești, Costești-Deal, Grădiștea de Munte, Ludeștii de Jos, Ludeștii de Sus and Ocolișu Mic. Much of the Dacian fortresses of the Orăștie Mountains, on the UNESCO World Heritage List, lie within its territory.","At Grădiștea de Munte lies the Dacian settlement of Sarmizegetusa Regia, the capital of the Dacian kingdom, and the Fețele Albe area has further Dacian remains. Costești has the Dacian fortresses of Costești–Blidaru and Costești–Cetățuie, while Bucium, Grădiștea de Munte and Costești-Deal keep Roman forts and Dacian fortifications.","The commune is part of the Grădiștea Muncelului–Cioclovina Nature Park. The churches of Orăștioara de Sus (1794), Bucium (1892–1900) and Ludeștii de Jos (1902) complete the local heritage."],"facts":[{"label":"Population","value":"1,910 (2021 census)"},{"label":"Villages","value":"Orăștioara de Sus, Bucium, Costești, Costești-Deal, Grădiștea de Munte, Ludeștii de Jos, Ludeștii de Sus, Ocolișu Mic"},{"label":"Landmarks","value":"Sarmizegetusa Regia, the Costești–Blidaru and Costești–Cetățuie fortresses, Fețele Albe (UNESCO)"},{"label":"Protected areas","value":"Grădiștea Muncelului–Cioclovina Nature Park, Natura 2000 site “Frumoasa”"}]}},{"id":"ghelari","name":"Ghelari","category":{"ro":"Comună","en":"Commune"},"area":"Poiana Ruscă","coords":[45.7167,22.7833],"hasReviews":false,"relatedAreas":["Ghelari"],"relatedIds":["furnalul-govajdia"],"images":["images/furnalul-govajdia.jpg"],"photoCredit":{"author":"RudolfHanzelik","license":"CC0 (domeniu public)","source":"https://commons.wikimedia.org/wiki/File:Blast_furnace_of_Govajdia.jpg"},"ro":{"tagline":"Comună minieră din Poiana Ruscă, cu Furnalul de la Govăjdia, un cuptor medieval de reducere a fierului și biserici vechi.","description":["Ghelari este o comună din Munții Poiana Ruscă, la circa 20 km de Hunedoara, formată din satele Ghelari (reședința), Govăjdia, Plop și Ruda. Zona are o veche tradiție în extracția și prelucrarea minereului de fier, de la care a pornit și industria siderurgică a Hunedoarei.","La Govăjdia se află Furnalul din 1806–1810, monument istoric, considerat primul furnal cu flux continuu din Europa. La Ghelari se păstrează un cuptor de reducere a fierului, o biserică de piatră din 1770 și o cruce memorială, iar la Ruda este biserica „Sfinții Arhangheli Mihail și Gavriil”, din 1653."],"facts":[{"label":"Populație","value":"1.501 locuitori (recensământ 2021)"},{"label":"Sate","value":"Ghelari, Govăjdia, Plop, Ruda"},{"label":"Repere","value":"Furnalul de la Govăjdia (1806–1810), cuptor de reducere a fierului la Ghelari, biserica din Ruda (1653), biserica de piatră din Ghelari (1770)"},{"label":"Distanță","value":"circa 20 km de Hunedoara"}]},"en":{"tagline":"A mining commune in the Poiana Ruscă range, with the Govăjdia Blast Furnace, a medieval iron-smelting furnace and old churches.","description":["Ghelari is a commune in the Poiana Ruscă Mountains, about 20 km from Hunedoara, made up of the villages of Ghelari (the seat), Govăjdia, Plop and Ruda. The area has a long tradition of mining and working iron ore, from which Hunedoara's steel industry also grew.","At Govăjdia stands the 1806–1810 Blast Furnace, a listed monument regarded as the first continuous-flow furnace in Europe. Ghelari keeps an iron-reduction furnace, a stone church from 1770 and a memorial cross, while Ruda has the Holy Archangels Michael and Gabriel church, from 1653."],"facts":[{"label":"Population","value":"1,501 (2021 census)"},{"label":"Villages","value":"Ghelari, Govăjdia, Plop, Ruda"},{"label":"Landmarks","value":"Govăjdia Blast Furnace (1806–1810), iron-reduction furnace at Ghelari, church in Ruda (1653), stone church in Ghelari (1770)"},{"label":"Distance","value":"about 20 km from Hunedoara"}]}},{"id":"bretea-romana","name":"Bretea Română","category":{"ro":"Comună","en":"Commune"},"area":"Țara Hațegului","coords":[45.6667,23.0167],"hasReviews":false,"relatedAreas":["Bretea Română"],"relatedIds":[],"images":["images/bretea-romana.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Bretea_Romana_(4).jpg"},"ro":{"tagline":"Comună din Țara Hațegului, cu treisprezece sate pe valea Streiului, biserici vechi și o villa rustica la Bățălar.","description":["Bretea Română este o comună din sud-vestul județului Hunedoara, la marginea Țării Hațegului, formată din 13 sate: Bretea Română (reședința), Bățălar, Bercu, Bretea Streiului, Covragiu, Gânțaga, Măceu, Ocolișu Mare, Plopi, Ruși, Vâlcele, Vâlcelele Bune și Vâlceluța.","În satul Bretea Română se păstrează o biserică ortodoxă din 1720, iar la Bățălar sunt vestigiile unei villa rustica romane. Comuna se află în apropierea Parcului Național Retezat și a sitului Natura 2000 „Strei–Hațeg”."],"facts":[{"label":"Populație","value":"2.969 locuitori (recensământ 2021)"},{"label":"Sate","value":"Bretea Română, Bățălar, Bercu, Bretea Streiului, Covragiu, Gânțaga, Măceu, Ocolișu Mare, Plopi, Ruși, Vâlcele, Vâlcelele Bune, Vâlceluța"},{"label":"Repere","value":"biserica ortodoxă din Bretea Română (1720), villa rustica de la Bățălar"},{"label":"Arii protejate","value":"situl Natura 2000 „Strei–Hațeg”"}]},"en":{"tagline":"A commune in Hațeg Country, with thirteen villages on the Strei valley, old churches and a villa rustica at Bățălar.","description":["Bretea Română is a commune in the south-west of Hunedoara County, on the edge of Hațeg Country, made up of 13 villages: Bretea Română (the seat), Bățălar, Bercu, Bretea Streiului, Covragiu, Gânțaga, Măceu, Ocolișu Mare, Plopi, Ruși, Vâlcele, Vâlcelele Bune and Vâlceluța.","The village of Bretea Română keeps an Orthodox church from 1720, and Bățălar has the remains of a Roman villa rustica. The commune lies near the Retezat National Park and the Natura 2000 site “Strei–Hațeg”."],"facts":[{"label":"Population","value":"2,969 (2021 census)"},{"label":"Villages","value":"Bretea Română, Bățălar, Bercu, Bretea Streiului, Covragiu, Gânțaga, Măceu, Ocolișu Mare, Plopi, Ruși, Vâlcele, Vâlcelele Bune, Vâlceluța"},{"label":"Landmarks","value":"Orthodox church in Bretea Română (1720), villa rustica at Bățălar"},{"label":"Protected areas","value":"Natura 2000 site “Strei–Hațeg”"}]}},{"id":"certeju-de-sus","name":"Certeju de Sus","category":{"ro":"Comună","en":"Commune"},"area":"Munții Metaliferi","coords":[45.9739,22.9703],"hasReviews":false,"relatedAreas":["Certeju de Sus"],"relatedIds":[],"images":["images/certeju-de-sus.jpg"],"photoCredit":{"author":"Oguszt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Katolikus_templom_nagyag.jpg"},"ro":{"tagline":"Comună minieră din Munții Metaliferi, cu Săcărâmb, Stânca lui Horea și Tăul Făerag, în zona aurului transilvănean.","description":["Certeju de Sus este o comună din nordul județului Hunedoara, în Munții Metaliferi, formată din satele Certeju de Sus (reședința), Bocșa Mare, Bocșa Mică, Hondol, Măgura-Toplița, Nojag, Săcărâmb, Toplița Mureșului și Vărmaga.","Zona este cunoscută ca zonă minieră din 1746, când Maria Terezia a decis relansarea mineritului aurifer. Prima topitorie de aur a fost deschisă în 1763 și a funcționat 119 ani. Stânca lui Horea amintește de mobilizarea minerilor în răscoala din 1784.","Pentru drumeție și odihnă există Tăul Făerag, un lac de acumulare de 4 ha, adânc de până la 8,7 m, și o cabană Romsilva. La Săcărâmb se află o biserică romano-catolică, iar rezervația „Măgurile Săcărâmbului” face parte din arealul comunei."],"facts":[{"label":"Populație","value":"2.870 locuitori (recensământ 2021)"},{"label":"Sate","value":"Certeju de Sus, Bocșa Mare, Bocșa Mică, Hondol, Măgura-Toplița, Nojag, Săcărâmb, Toplița Mureșului, Vărmaga"},{"label":"Repere","value":"Stânca lui Horea, Tăul Făerag (4 ha), biserica romano-catolică din Săcărâmb"},{"label":"Istoric minier","value":"zonă minieră din 1746; prima topitorie de aur din 1763 (119 ani)"}]},"en":{"tagline":"A mining commune in the Metaliferi Mountains, with Săcărâmb, Horea's Rock and Făerag Lake, in the heart of Transylvanian gold country.","description":["Certeju de Sus is a commune in the north of Hunedoara County, in the Metaliferi Mountains, made up of the villages of Certeju de Sus (the seat), Bocșa Mare, Bocșa Mică, Hondol, Măgura-Toplița, Nojag, Săcărâmb, Toplița Mureșului and Vărmaga.","The area has been a mining zone since 1746, when Maria Theresa decided to revive gold mining. The first gold smelter opened in 1763 and ran for 119 years. Horea's Rock recalls the mobilisation of miners in the 1784 uprising.","For walks and relaxation there is Făerag Lake, a 4 ha reservoir up to 8.7 m deep, and a Romsilva lodge. Săcărâmb has a Roman Catholic church, and the “Săcărâmb Hillocks” reserve lies in the commune's area."],"facts":[{"label":"Population","value":"2,870 (2021 census)"},{"label":"Villages","value":"Certeju de Sus, Bocșa Mare, Bocșa Mică, Hondol, Măgura-Toplița, Nojag, Săcărâmb, Toplița Mureșului, Vărmaga"},{"label":"Landmarks","value":"Horea's Rock, Făerag Lake (4 ha), Roman Catholic church in Săcărâmb"},{"label":"Mining history","value":"mining zone since 1746; first gold smelter from 1763 (119 years)"}]}},{"id":"baru","name":"Baru","category":{"ro":"Comună","en":"Commune"},"area":"Țara Hațegului","coords":[45.4864,23.1765],"hasReviews":false,"relatedAreas":["Baru","Baru Mare"],"relatedIds":["traseu-baru-varful-tulisa","traseu-baru-varful-lola-porumbelu"],"images":["images/baru.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Biserica_monument_din_Baru_Mare_(10).JPG"},"ro":{"tagline":"Comună de la poalele Retezatului și Șureanului, cu Cheile Barului, Peștera Tecuri, biserici vechi și un muzeu de artă populară.","description":["Baru este o comună din sud-vestul județului Hunedoara, formată din satele Baru (reședința), Livadia, Petros și Valea Lupului. Este un punct de plecare pentru trasee spre Retezat și spre Munții Șureanu.","Printre obiective se numără biserica „Sfântul Ilie” din Baru (monument istoric), biserica Pârveștilor din secolul al XVIII-lea, muzeul de artă populară „Maria Hord Gârbea”, castrul roman și situl arheologic de la Baru și villa rustica de la Valea Lupului.","În natură sunt Cheile Barului și rezervația „Peștera Tecuri” (2 ha)."],"facts":[{"label":"Populație","value":"2.425 locuitori (recensământ 2021)"},{"label":"Sate","value":"Baru, Livadia, Petros, Valea Lupului"},{"label":"Repere","value":"biserica „Sfântul Ilie”, biserica Pârveștilor (sec. XVIII), muzeul „Maria Hord Gârbea”, castrul roman de la Baru"},{"label":"Natură","value":"Cheile Barului, rezervația „Peștera Tecuri” (2 ha)"}]},"en":{"tagline":"A commune at the foot of the Retezat and Șureanu mountains, with the Baru Gorge, Tecuri Cave, old churches and a folk-art museum.","description":["Baru is a commune in the south-west of Hunedoara County, made up of the villages of Baru (the seat), Livadia, Petros and Valea Lupului. It is a starting point for trails into the Retezat and the Șureanu Mountains.","Its sights include Saint Elijah Church in Baru (a listed monument), the 18th-century Pârveștilor Church, the “Maria Hord Gârbea” folk-art museum, the Roman fort and archaeological site at Baru and the villa rustica at Valea Lupului.","Natural attractions are the Baru Gorge and the “Tecuri Cave” reserve (2 ha)."],"facts":[{"label":"Population","value":"2,425 (2021 census)"},{"label":"Villages","value":"Baru, Livadia, Petros, Valea Lupului"},{"label":"Landmarks","value":"Saint Elijah Church, Pârveștilor Church (18th c.), “Maria Hord Gârbea” museum, Roman fort at Baru"},{"label":"Nature","value":"Baru Gorge, “Tecuri Cave” reserve (2 ha)"}]}},{"id":"romos","name":"Romos","category":{"ro":"Comună","en":"Commune"},"area":"Culoarul Mureșului","coords":[45.8173,23.3082],"hasReviews":false,"relatedAreas":["Romos"],"relatedIds":[],"images":["images/romos.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Biserica_Înălțarea_Domnului_din_Romos_(1).jpg"},"ro":{"tagline":"Comună de lângă Orăștie, cu ansamblul rural Romos, biserica evanghelică și biserici vechi din secolele XVIII–XIX.","description":["Romos este o comună din centrul județului Hunedoara, formată din satele Romos (reședința), Ciungu Mare, Pișchinți, Romoșel și Vaidei. Satul Romos păstrează un ansamblu rural declarat monument istoric.","Aici se află biserica evanghelică-luterană, casa parohială evanghelică din secolul al XVIII-lea și biserica „Înălțarea Domnului”, din 1775. La Romoșel sunt biserica ortodoxă „Pogorârea Sfântului Duh” (1847) și biserica greco-catolică „Adormirea Maicii Domnului” (1839)."],"facts":[{"label":"Populație","value":"2.388 locuitori (recensământ 2021)"},{"label":"Sate","value":"Romos, Ciungu Mare, Pișchinți, Romoșel, Vaidei"},{"label":"Repere","value":"ansamblul rural Romos, biserica evanghelică-luterană, casa parohială evanghelică (sec. XVIII), biserica „Înălțarea Domnului” (1775)"}]},"en":{"tagline":"A commune near Orăștie, with the Romos rural ensemble, a Lutheran church and old 18th–19th-century churches.","description":["Romos is a commune in the centre of Hunedoara County, made up of the villages of Romos (the seat), Ciungu Mare, Pișchinți, Romoșel and Vaidei. The village of Romos keeps a rural ensemble listed as a historic monument.","It has the Evangelical-Lutheran church, the 18th-century Evangelical parish house and the Church of the Ascension, from 1775. Romoșel has the Orthodox church of the Descent of the Holy Spirit (1847) and the Greek-Catholic church of the Dormition (1839)."],"facts":[{"label":"Population","value":"2,388 (2021 census)"},{"label":"Villages","value":"Romos, Ciungu Mare, Pișchinți, Romoșel, Vaidei"},{"label":"Landmarks","value":"Romos rural ensemble, Evangelical-Lutheran church, Evangelical parish house (18th c.), Church of the Ascension (1775)"}]}},{"id":"teliucu-inferior","name":"Teliucu Inferior","category":{"ro":"Comună","en":"Commune"},"area":"Poiana Ruscă","coords":[45.7178,22.8869],"hasReviews":false,"relatedAreas":["Teliucu Inferior","Cinciș-Cerna"],"relatedIds":["lacul-cincis"],"images":["images/lacul-cincis.jpg"],"photoCredit":{"author":"Raydu18","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Cincis.jpg"},"ro":{"tagline":"Comună din Poiana Ruscă, cu Lacul Cinciș, situri arheologice romane la Cinciș-Cerna și o veche tradiție minieră la Teliuc.","description":["Teliucu Inferior este o comună din Munții Poiana Ruscă, lângă Hunedoara, formată din satele Teliucu Inferior (reședința), Cinciș-Cerna, Izvoarele și Teliucu Superior.","Pe teritoriul ei se află Lacul Cinciș, un lac de acumulare cunoscut pentru plajă și pescuit. La Cinciș-Cerna sunt un sit arheologic, o necropolă tumulară și o villa rustica romană.","Teliuc a fost în antichitate un important loc de exploatare de suprafață, iar un atelier dacico-roman de aici furniza fier pentru Legiunea a XIII-a Gemina de la Apulum și pentru capitala provinciei, Sarmizegetusa."],"facts":[{"label":"Populație","value":"2.022 locuitori (recensământ 2021)"},{"label":"Sate","value":"Teliucu Inferior, Cinciș-Cerna, Izvoarele, Teliucu Superior"},{"label":"Repere","value":"Lacul Cinciș, necropola tumulară și villa rustica de la Cinciș-Cerna"},{"label":"Istoric","value":"exploatare de fier în epoca dacico-romană la Teliuc"}]},"en":{"tagline":"A commune in the Poiana Ruscă range, with Cincis Lake, Roman archaeological sites at Cinciș-Cerna and an old mining tradition at Teliuc.","description":["Teliucu Inferior is a commune in the Poiana Ruscă Mountains, near Hunedoara, made up of the villages of Teliucu Inferior (the seat), Cinciș-Cerna, Izvoarele and Teliucu Superior.","Its territory includes Cincis Lake, a reservoir known for its beach and fishing. Cinciș-Cerna has an archaeological site, a tumular necropolis and a Roman villa rustica.","Teliuc was an important surface-mining site in antiquity, and a Dacian-Roman workshop there supplied iron to Legio XIII Gemina at Apulum and to the provincial capital, Sarmizegetusa."],"facts":[{"label":"Population","value":"2,022 (2021 census)"},{"label":"Villages","value":"Teliucu Inferior, Cinciș-Cerna, Izvoarele, Teliucu Superior"},{"label":"Landmarks","value":"Cincis Lake, tumular necropolis and villa rustica at Cinciș-Cerna"},{"label":"History","value":"iron extraction in Dacian-Roman times at Teliuc"}]}},{"id":"turdas","name":"Turdaș","category":{"ro":"Comună","en":"Commune"},"area":"Culoarul Mureșului","coords":[45.85,23.1333],"hasReviews":false,"relatedAreas":["Turdaș"],"relatedIds":[],"images":["images/placeholder.svg"],"ro":{"tagline":"Comună de pe Mureș, cunoscută pentru așezarea neolitică din cultura Vinča–Turdaș și pentru ansamblul bisericii reformate din secolul al XV-lea.","description":["Turdaș este o comună din centrul județului Hunedoara, formată din satele Turdaș (reședința), Pricaz, Râpaș și Spini.","Cea mai cunoscută este așezarea neolitică de la Turdaș, asociată culturii Vinča–Turdaș: o probabilă așezare fortificată de tip proto-urban și centru regional de olărit, cu șase straturi de locuire, din neoliticul timpuriu până în perioada medievală.","Printre monumentele istorice se numără ansamblul bisericii reformate din Turdaș (secolul al XV-lea) și ansamblurile rurale Turdaș și Pricaz, din secolul al XIX-lea."],"facts":[{"label":"Populație","value":"1.791 locuitori (recensământ 2021)"},{"label":"Sate","value":"Turdaș, Pricaz, Râpaș, Spini"},{"label":"Repere","value":"așezarea neolitică Vinča–Turdaș, ansamblul bisericii reformate (sec. XV), ansamblurile rurale Turdaș și Pricaz"}]},"en":{"tagline":"A commune on the Mureș, known for its Neolithic settlement of the Vinča–Turdaș culture and its 15th-century Reformed church ensemble.","description":["Turdaș is a commune in the centre of Hunedoara County, made up of the villages of Turdaș (the seat), Pricaz, Râpaș and Spini.","Best known is the Neolithic settlement at Turdaș, linked to the Vinča–Turdaș culture: a probable fortified proto-urban settlement and regional pottery centre, with six occupation layers from the early Neolithic to the medieval period.","Listed monuments include the Reformed church ensemble in Turdaș (15th century) and the rural ensembles of Turdaș and Pricaz, from the 19th century."],"facts":[{"label":"Population","value":"1,791 (2021 census)"},{"label":"Villages","value":"Turdaș, Pricaz, Râpaș, Spini"},{"label":"Landmarks","value":"Vinča–Turdaș Neolithic settlement, Reformed church ensemble (15th c.), Turdaș and Pricaz rural ensembles"}]}},{"id":"rapoltu-mare","name":"Rapoltu Mare","category":{"ro":"Comună","en":"Commune"},"area":"Culoarul Mureșului","coords":[45.865,23.0753],"hasReviews":false,"relatedAreas":["Rapoltu Mare"],"relatedIds":[],"images":["images/rapoltu-mare.jpg"],"photoCredit":{"author":"Utilizator:Țetcu Mircea Rareș at ro.wikipedia","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Bobalna_2.jpg"},"ro":{"tagline":"Comună de la poalele Munților Metaliferi, cu biserica reformată din secolul al XIV-lea, castelul Veress din Bobâlna și Tufurile calcaroase din Valea Bobâlnei.","description":["Rapoltu Mare este o comună din centrul județului Hunedoara, formată din satele Rapoltu Mare (reședința), Bobâlna, Boiu, Folt și Rapolțel.","Aici se află biserica reformată din Rapoltu Mare (secolul al XIV-lea), conacul Daniel și castelul contelui Veress din Bobâlna (secolul al XVIII-lea). În zonă sunt și situl arheologic de la Măgura Uroiului și o așezare din epoca bronzului.","Rezervațiile „Tufurile calcaroase din Valea Bobâlnei” și „Măgura Uroiului” completează oferta naturală. Aici s-a născut Atanasie Anghel, mitropolit al Bălgradului (m. 1713)."],"facts":[{"label":"Populație","value":"1.788 locuitori (recensământ 2021)"},{"label":"Sate","value":"Rapoltu Mare, Bobâlna, Boiu, Folt, Rapolțel"},{"label":"Repere","value":"biserica reformată (sec. XIV), castelul Veress din Bobâlna (sec. XVIII), conacul Daniel, Măgura Uroiului"},{"label":"Natură","value":"rezervațiile „Tufurile calcaroase din Valea Bobâlnei” și „Măgura Uroiului”"}]},"en":{"tagline":"A commune at the foot of the Metaliferi Mountains, with a 14th-century Reformed church, the Veress castle at Bobâlna and the Bobâlna Valley limestone tuffs.","description":["Rapoltu Mare is a commune in the centre of Hunedoara County, made up of the villages of Rapoltu Mare (the seat), Bobâlna, Boiu, Folt and Rapolțel.","It has the Reformed church of Rapoltu Mare (14th century), the Daniel manor and Count Veress's castle at Bobâlna (18th century). Nearby are the archaeological site at Măgura Uroiului and a Bronze Age settlement.","The “Bobâlna Valley limestone tuffs” and “Măgura Uroiului” reserves complete the natural offer. Atanasie Anghel, Metropolitan of Bălgrad (d. 1713), was born here."],"facts":[{"label":"Population","value":"1,788 (2021 census)"},{"label":"Villages","value":"Rapoltu Mare, Bobâlna, Boiu, Folt, Rapolțel"},{"label":"Landmarks","value":"Reformed church (14th c.), Veress castle at Bobâlna (18th c.), Daniel manor, Măgura Uroiului"},{"label":"Nature","value":"“Bobâlna Valley limestone tuffs” and “Măgura Uroiului” reserves"}]}},{"id":"bacia","name":"Băcia","category":{"ro":"Comună","en":"Commune"},"area":"Valea Streiului","coords":[45.8028,23.0069],"hasReviews":false,"relatedAreas":["Băcia"],"relatedIds":[],"images":["images/bacia.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Biserica_Sfântul_Mare_Mucenic_Gheorghe_din_Băcia_(6).jpg"},"ro":{"tagline":"Comună de pe valea Streiului, cunoscută pentru casa memorială și mormântul lui Petru Groza, și pentru bisericile ei vechi.","description":["Băcia este o comună din județul Hunedoara, la 225 m altitudine, pe valea Streiului, formată din satele Băcia (reședința), Petreni, Tâmpa și Totia. Pe teritoriul ei se intersectează două drumuri importante, simbolizate pe stemă prin crucea Sfântului Andrei.","În Băcia se află casa memorială Petru Groza și mormântul acestuia. Satul are biserica „Sfântul Mare Mucenic Gheorghe” (monument istoric), biserica „Pogorârea Sfântului Duh” (1873–1876) și biserica reformată (1865). Stema comunei amintește de prelucrarea pietrelor de moară și de dalele de marmură."],"facts":[{"label":"Populație","value":"1.734 locuitori (recensământ 2021)"},{"label":"Sate","value":"Băcia, Petreni, Tâmpa, Totia"},{"label":"Repere","value":"casa memorială și mormântul Petru Groza, biserica „Sfântul Gheorghe”, biserica „Pogorârea Sfântului Duh” (1873–1876)"}]},"en":{"tagline":"A commune on the Strei valley, known for Petru Groza's memorial house and grave, and for its old churches.","description":["Băcia is a commune in Hunedoara County, at 225 m altitude on the Strei valley, made up of the villages of Băcia (the seat), Petreni, Tâmpa and Totia. Two important roads cross on its territory, symbolised on the coat of arms by Saint Andrew's cross.","Băcia has the Petru Groza memorial house and his grave. The village has Saint George the Great Martyr church (a listed monument), the Descent of the Holy Spirit church (1873–1876) and the Reformed church (1865). The commune's coat of arms recalls millstone working and marble slabs."],"facts":[{"label":"Population","value":"1,734 (2021 census)"},{"label":"Villages","value":"Băcia, Petreni, Tâmpa, Totia"},{"label":"Landmarks","value":"Petru Groza memorial house and grave, Saint George church, Descent of the Holy Spirit church (1873–1876)"}]}}];
